/* Banco de perguntas: Eletrostática.
   Campos: id, t (área), q (enunciado), o (alternativas), a (índice da correta), h (dica), e (explicação),
   f (figura, opcional), v (1 = ordem fixa, usado em verdadeiro/falso), c (1 = exige cálculo; fica fora do modo cronometrado). */
window.BANKS=window.BANKS||{};
window.BANKS.eletro=[{"id": "q001", "an": "atrito_transfer", "t": "el", "q": "Um bastão de plástico atritado com lã fica negativo. Qual afirmação é correta?", "o": ["A lã perdeu elétrons e ficou positiva, com carga de mesmo módulo.", "A lã ganhou prótons e ficou positiva, com carga de mesmo módulo.", "A lã ficou neutra, pois só o plástico trocou carga com o ambiente.", "A lã ficou negativa, com carga de mesmo sinal que o plástico."], "a": 0, "h": "Pense em quem recebeu elétrons e no que sobra para o outro corpo.", "e": "A lã cedeu elétrons ao plástico. Ela ficou com carga positiva de mesmo valor absoluto, já que a carga total do sistema continua nula.", "f": "atrito", "x": {"1": "Quem se transfere são os elétrons, não os prótons, que ficam presos ao núcleo.", "2": "A lã participa: se o plástico ficou negativo, ela perdeu elétrons e não ficou neutra.", "3": "Se o plástico ganhou elétrons, a lã perdeu: tem sinal oposto, e não o mesmo."}, "n": 2}, {"id": "q002", "t": "el", "q": "A esfera A (+6 µC) toca a esfera B (−2 µC), idêntica. Qual é a carga final de cada uma?", "o": ["+2 µC em cada esfera", "+4 µC em A e −4 µC em B", "+3 µC em A e −1 µC em B", "+4 µC em cada esfera"], "a": 0, "h": "Some as cargas com sinal antes de dividir.", "e": "A carga total é +6 + (−2) = +4 µC. Esferas idênticas dividem igualmente: +2 µC cada.", "f": "contato", "c": 1, "x": {"1": "Cargas que se tocam se redistribuem; elas não ficam com valores opostos.", "2": "A soma é +4 µC, divididos igualmente: +2 µC cada, não +3 e −1.", "3": "+4 µC em cada daria total +8 µC, mas a soma total é +4 µC."}, "an": "contato_q002", "n": 2}, {"id": "q003", "t": "el", "q": "Por que uma esfera metálica neutra é atraída por um bastão positivo, mesmo sem tocá-lo?", "o": ["Os elétrons livres vão para o lado próximo, e a atração vence a repulsão.", "O bastão transfere carga à esfera pelo ar, e ela fica toda positiva.", "O bastão cria elétrons novos no lado da esfera mais próximo dele.", "A esfera fica toda negativa e é atraída por inteiro pelo bastão."], "a": 0, "h": "Compare as distâncias entre o bastão e cada lado da esfera.", "e": "Os elétrons livres migram para o lado próximo. A atração (cargas mais próximas) vence a repulsão (cargas mais distantes), embora a esfera continue neutra no total.", "f": "inducao", "x": {"1": "Não há transferência pelo ar. A esfera continua neutra no total, só se polariza.", "2": "Elétrons não são criados, apenas se deslocam.", "3": "A esfera segue neutra: apenas as cargas se separam."}, "an": "inducao", "n": 2}, {"id": "q004", "t": "el", "q": "Com o bastão positivo ainda perto, a esfera é ligada à terra. Depois, desliga-se a terra e afasta-se o bastão. O que se observa?", "o": ["Elétrons vêm da terra para a esfera, que fica negativa.", "Elétrons vão da esfera para a terra, e ela fica positiva.", "Prótons vêm da terra para a esfera, que fica positiva.", "Nada muda, e a esfera continua neutra depois disso."], "a": 0, "h": "O bastão positivo atrai cargas negativas, e a terra pode fornecê-las.", "e": "O bastão positivo atrai elétrons da terra. Ao cortar a ligação antes de afastar o bastão, a esfera retém o excesso e fica negativa, de sinal oposto ao do indutor.", "f": "terra", "x": {"1": "Com o bastão positivo perto, os elétrons são atraídos para a esfera, e não o contrário.", "2": "Prótons não se movem em condutores.", "3": "A esfera fica carregada: a ligação à terra permitiu a entrada de elétrons."}, "an": "terra_pos", "n": 3}, {"id": "q005", "t": "el", "q": "A esfera A (+9 µC) toca a B, depois B toca a C (A, B e C idênticas; B e C começam neutras). Qual é a carga final de C?", "o": ["+2,25 µC", "+3 µC", "+4,5 µC", "+1,5 µC"], "a": 0, "h": "Divida a carga em duas etapas, uma para cada contato.", "e": "A e B ficam com +4,5 µC cada. Depois B (+4,5) toca C (0): ficam +2,25 µC cada. Logo C termina com +2,25 µC.", "c": 1, "x": {"1": "+3 µC dividiria 9 em três partes. Aqui há duas divisões sucessivas por 2.", "2": "+4,5 µC é a carga de B após o primeiro contato, não de C.", "3": "+1,5 µC seria divisão por 6."}, "an": "contato_q005", "n": 3}, {"id": "q006", "an": "calc_q006", "t": "el", "q": "Um corpo fica com carga de −3,2 µC. Quantos elétrons em excesso ele possui? (e = 1,6 × 10⁻¹⁹ C)", "o": ["2 × 10¹³", "5 × 10¹³", "2 × 10⁻¹³", "5 × 10⁻¹³"], "a": 0, "h": "Use n = |Q| / e, convertendo µC para C.", "e": "n = 3,2 × 10⁻⁶ / 1,6 × 10⁻¹⁹ = 2 × 10¹³ elétrons em excesso.", "c": 1, "x": {"1": "5 × 10¹³ inverteu a divisão.", "2": "O expoente tem sinal errado: o número de elétrons é muito grande.", "3": "Além do expoente, a divisão está invertida."}, "n": 2}, {"id": "q007", "t": "el", "q": "Pedacinhos de papel são atraídos por um pente atritado. Como o papel, um isolante, explica isso?", "o": ["As moléculas se orientam, e surge uma atração líquida.", "Os elétrons fluem livremente até um dos lados do papel.", "O papel é condutor e se carrega por indução com a terra.", "O papel ganha carga por contato e depois é repelido."], "a": 0, "h": "Em isolantes, as cargas não conseguem se mover livremente.", "e": "É a polarização. Sem elétrons livres, cada molécula só se orienta ou deforma, o que basta para uma atração líquida.", "x": {"1": "No isolante os elétrons não fluem livremente; só as moléculas se orientam.", "2": "O papel é isolante, não condutor.", "3": "O papel não precisa tocar o pente: a atração ocorre antes, por polarização."}, "an": "polariz", "n": 2}, {"id": "q008", "t": "el", "q": "Um bastão negativo é aproximado, sem tocar, do botão de um eletroscópio de folhas neutro. As folhas se abrem. Por quê?", "o": ["Elétrons vão do botão às folhas, que se repelem.", "O eletroscópio fica negativo e as folhas se atraem.", "Prótons passam do bastão para as folhas, que se abrem.", "As folhas ficam positivas e se afastam do botão."], "a": 0, "h": "O bastão negativo repele os elétrons livres do metal.", "e": "Os elétrons são repelidos do botão para as folhas. Elas ficam negativas e se repelem, mas o eletroscópio continua neutro no total. Afastado o bastão, as folhas se fecham.", "x": {"1": "O eletroscópio fica neutro no total; e as folhas, ao terem cargas iguais, se repelem.", "2": "O bastão não transfere prótons, e nem toca o botão.", "3": "As folhas ficam negativas, não positivas, pois os elétrons migram para elas."}, "an": "eletroscopio_neg", "n": 2}, {"id": "q009", "t": "el", "q": "Qual comparação entre os processos está correta?", "o": ["Atrito: sinais opostos; contato: mesmo sinal; indução: sinal oposto.", "Atrito: mesmo sinal; contato: sinais opostos; indução: neutros.", "Atrito: sinais opostos; contato: sinal oposto; indução: mesmo sinal.", "Atrito: mesmo sinal; contato: mesmo sinal; indução: sinal oposto."], "a": 0, "h": "Veja de onde vem o sinal final em cada processo.", "e": "Atrito: corpos com sinais opostos. Contato: o neutro adquire o sinal do corpo carregado. Indução: o induzido fica com sinal oposto ao do indutor.", "x": {"1": "No atrito os corpos ficam com sinais opostos e no contato com o mesmo sinal, não ao contrário.", "2": "No contato os corpos ficam com cargas de mesmo sinal, não oposto.", "3": "No atrito os corpos ficam com sinais opostos, não iguais."}, "n": 2}, {"id": "q010", "t": "el", "q": "Numa série triboelétrica, A atritado com B fica positivo, e B atritado com C fica positivo. Se A for atritado com C, o que acontece?", "o": ["A fica positivo e C fica negativo.", "C fica positivo e A fica negativo.", "A e C ficam neutros após o atrito.", "Os dois ficam positivos, pois ambos perdem elétrons."], "a": 0, "h": "Ordene A, B e C pela tendência de perder elétrons.", "e": "A tende a perder elétrons mais que B, e B mais que C. Assim, A perde mais que C: A fica positivo e C, negativo.", "x": {"1": "A é mais positivo que B e B mais que C, então A é o mais positivo.", "2": "Eles ficam eletrizados, porque estão em posições diferentes na série.", "3": "Atritando corpos diferentes, um perde e o outro ganha elétrons."}, "n": 3}, {"id": "q011", "an": "atrito_transfer", "t": "el", "q": "Qual partícula é transferida de um corpo para outro nos processos de eletrização?", "o": ["Elétrons", "Prótons", "Nêutrons", "Núcleos inteiros"], "a": 0, "h": "É a partícula que fica fora do núcleo do átomo.", "e": "Os elétrons são os que se movem. Os prótons ficam presos ao núcleo e não se transferem nesses processos.", "x": {"1": "Prótons ficam no núcleo e não se transferem nesses processos.", "2": "Nêutrons não têm carga.", "3": "Núcleos inteiros não se transferem."}, "n": 1}, {"id": "q012", "an": "par_forcas", "t": "el", "q": "O que acontece entre duas cargas de mesmo sinal e entre duas de sinais opostos?", "o": ["Mesmo sinal se repele; sinais opostos se atraem.", "Mesmo sinal se atrai; sinais opostos se repelem.", "Cargas de qualquer sinal sempre se repelem.", "Cargas de qualquer sinal sempre se atraem."], "a": 0, "h": "Revise a lei básica de interação entre cargas.", "e": "Cargas de mesmo sinal se repelem e cargas de sinais opostos se atraem. É por isso que um corpo neutro pode ser atraído por um corpo carregado.", "x": {"1": "Está invertido: mesmo sinal se repele.", "2": "Cargas opostas se atraem.", "3": "Cargas de mesmo sinal se repelem."}, "n": 1}, {"id": "q013", "t": "el", "q": "Ao atritar um bastão de vidro com seda, só a região atritada fica carregada. Por quê?", "o": ["O vidro é isolante, e as cargas não se espalham livremente.", "O vidro é condutor, mas a seda impede as cargas de se moverem.", "A carga some assim que o atrito termina e o bastão é solto.", "As cargas positivas ficam fixas e as negativas fluem pelo vidro."], "a": 0, "h": "Compare como as cargas se movem em isolantes e em metais.", "e": "Em isolantes os elétrons não se movem livremente pelo material, então a carga fica localizada onde foi gerada. Em um metal ela se espalharia.", "x": {"1": "O vidro é isolante, não condutor.", "2": "A carga não some assim que o atrito acaba.", "3": "Em isolantes nenhuma carga flui livremente."}, "n": 2}, {"id": "q014", "t": "el", "q": "A esfera A (−8 µC) toca B (+2 µC), idêntica. Depois B toca C (+6 µC), também idêntica. Qual é a carga final de C?", "o": ["+1,5 µC", "+3 µC", "−1,5 µC", "+2 µC"], "a": 0, "h": "Faça duas etapas, somando as cargas com sinal e dividindo por dois.", "e": "A e B ficam com (−8 + 2)/2 = −3 µC. Depois B (−3) toca C (+6): (−3 + 6)/2 = +1,5 µC. Logo C termina com +1,5 µC.", "c": 1, "x": {"1": "+3 µC não segue os dois contatos sucessivos.", "2": "O sinal está errado.", "3": "+2 µC é a carga de B antes do contato com C, não de C no final."}, "an": "contato_q014", "n": 3}, {"id": "q015", "t": "el", "q": "A esfera A (+4 µC) toca B (−8 µC), idêntica. Quantos elétrons passam de B para A até o equilíbrio? (e = 1,6 × 10⁻¹⁹ C)", "o": ["3,75 × 10¹³", "1,25 × 10¹³", "7,5 × 10¹³", "2,5 × 10¹³"], "a": 0, "h": "Ache a carga final de cada esfera e veja quanto A variou.", "e": "A carga final é (4 − 8)/2 = −2 µC em cada. A passou de +4 para −2 µC, variação de 6 µC. n = 6 × 10⁻⁶ / 1,6 × 10⁻¹⁹ = 3,75 × 10¹³ elétrons.", "c": 1, "x": {"1": "1,25 × 10¹³ corresponde a uma transferência de 2 µC.", "2": "7,5 × 10¹³ corresponde a 12 µC.", "3": "2,5 × 10¹³ corresponde a 4 µC."}, "an": "contato_q015", "n": 3}, {"id": "q016", "an": "atrito_transfer", "t": "el", "q": "Duas esferas trocam carga em um sistema isolado. O que se conserva?", "o": ["A soma algébrica das cargas permanece constante.", "A carga de cada esfera permanece a mesma de antes.", "O número de prótons de cada esfera muda no processo.", "A soma dos módulos das cargas nunca pode variar."], "a": 0, "h": "Pense no que a troca de elétrons não altera no total.", "e": "Cargas não são criadas nem destruídas, apenas redistribuídas. A soma algébrica se conserva, mas a soma dos módulos pode mudar (+6 e −2 viram +2 e +2).", "x": {"1": "As cargas de cada esfera mudam, só a soma permanece.", "2": "O número de prótons não muda nesses processos.", "3": "O que se conserva é a soma algébrica, não a soma dos módulos."}, "n": 1}, {"id": "q017", "an": "metal_mao", "t": "el", "q": "Por que uma barra de metal segurada na mão e atritada não fica eletrizada?", "o": ["A carga escoa pelo corpo da pessoa até a terra.", "Metais não possuem elétrons que possam ser transferidos.", "O atrito com metais nunca gera troca de elétrons.", "A barra cria prótons que neutralizam os elétrons trocados."], "a": 0, "h": "Pense no caminho que a carga encontra: metal, mão, corpo...", "e": "O metal e o corpo humano conduzem. A carga gerada escoa até a terra e a barra não fica eletrizada. Com um cabo isolante, ela se eletrizaria.", "x": {"1": "Metais têm elétrons livres.", "2": "Metais podem trocar elétrons no atrito.", "3": "A barra não cria prótons."}, "n": 2}, {"id": "q018", "t": "el", "q": "Um bastão negativo se aproxima de uma esfera metálica neutra, que é ligada à terra, desligada e então fica sozinha após o bastão ser afastado. Qual é a carga final da esfera?", "o": ["Positiva, pois elétrons foram para a terra.", "Negativa, pois elétrons vieram da terra.", "Neutra, pois a ligação à terra desfaz a carga.", "Positiva, pois a esfera ganhou prótons da terra."], "a": 0, "h": "O bastão negativo repele elétrons da esfera.", "e": "O bastão repele os elétrons para a terra. Cortada a ligação com o bastão ainda perto, a esfera fica com falta de elétrons: positiva, de sinal oposto ao do indutor.", "x": {"1": "Com o bastão negativo perto, os elétrons saem da esfera para a terra.", "2": "A ligação à terra não neutraliza a esfera, porque o bastão está presente.", "3": "Prótons não se movem em condutores."}, "an": "terra_neg", "n": 3}, {"id": "q019", "an": "choque", "t": "el", "q": "Em dia seco, você anda sobre um carpete e leva um choque ao tocar numa maçaneta metálica. Qual é a explicação?", "o": ["O atrito eletrizou você, e a carga passa à maçaneta ao tocar.", "A maçaneta cria elétrons novos ao ser tocada pela mão.", "O carpete transfere prótons para você durante a caminhada.", "Você fica neutro, e a maçaneta atrai cargas do ar seco."], "a": 0, "h": "Pense no atrito entre a sola e o carpete e em quem fica com excesso de carga.", "e": "O atrito com o carpete deixa seu corpo com excesso de carga. Ao tocar o metal, ela escoa rapidamente, produzindo a faísca e o choque.", "x": {"1": "A maçaneta não cria elétrons.", "2": "Prótons não se transferem.", "3": "O ar seco não atrai cargas. É o atrito que eletriza."}, "n": 2}, {"id": "q020", "an": "coul_grafico", "t": "co", "q": "Verdadeiro ou falso: dobrando a distância entre duas cargas, a força elétrica entre elas cai para a quarta parte.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Lembre a forma da lei de Coulomb: F = k·|q₁·q₂| / d².", "e": "A força é inversamente proporcional ao quadrado da distância. Dobrar d divide F por 2² = 4.", "v": 1, "x": {"1": "Dobrando a distância, a força cai para 1/4. A afirmação é verdadeira."}, "n": 1}, {"id": "q021", "t": "co", "q": "Duas cargas iguais, separadas por uma distância d, se repelem com força F. Se a distância passar a 3d, a nova força será:", "o": ["F/9", "F/3", "3F", "9F"], "a": 0, "h": "A força varia com o inverso do quadrado da distância.", "e": "F ∝ 1/d². Com 3d, a força fica 1/3² = 1/9 do valor inicial.", "f": "coulomb", "x": {"1": "F/3 seria a lei se fosse proporcional a 1/d. Mas F ∝ 1/d².", "2": "3F não faz sentido: a força diminui.", "3": "9F trocou a direção: a força cai para 1/9."}, "an": "coul_d3", "n": 2}, {"id": "q022", "an": "par_forcas", "t": "co", "q": "Duas cargas, q e 2q, estão a uma distância d. Qual afirmação sobre a força entre elas está correta?", "o": ["Tem o mesmo módulo e sentidos opostos nas duas cargas.", "É maior na carga 2q e menor na carga q.", "É maior na carga q, que tem menos carga.", "É nula, pois as cargas têm valores diferentes."], "a": 0, "h": "Pense na terceira lei de Newton (ação e reação).", "e": "As forças elétricas formam um par de ação e reação: mesmo módulo, mesma direção e sentidos opostos, mesmo com cargas diferentes.", "x": {"1": "Pela terceira lei de Newton, as forças são iguais em módulo.", "2": "A força é igual nas duas cargas.", "3": "A força não é nula: ela depende do produto das cargas."}, "n": 2}, {"id": "q023", "an": "calc_q023", "t": "co", "q": "Duas cargas de +2 µC e +3 µC estão a 0,3 m no vácuo. Qual é a intensidade da força entre elas? (k = 9 × 10⁹ N·m²/C²)", "o": ["0,6 N", "0,06 N", "6 N", "1,8 N"], "a": 0, "h": "Use F = k·q₁·q₂ / d², com as cargas em coulombs.", "e": "F = 9 × 10⁹ × 2 × 10⁻⁶ × 3 × 10⁻⁶ / (0,3)² = 5,4 × 10⁻² / 0,09 = 0,6 N, de repulsão.", "c": 1, "x": {"1": "0,06 N tem fator 10 a menos.", "2": "6 N tem fator 10 a mais.", "3": "1,8 N usa d no lugar de d²."}, "n": 2}, {"id": "q024", "an": "linhas_neg", "t": "ca", "q": "Verdadeiro ou falso: uma carga de prova positiva colocada perto de uma carga negativa é puxada na direção dela.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Lembre como interagem cargas de sinais opostos.", "e": "Cargas de sinais opostos se atraem. Por isso o campo de uma carga negativa aponta para ela.", "v": 1, "x": {"1": "Cargas opostas se atraem. A afirmação é verdadeira."}, "n": 1}, {"id": "q025", "t": "ca", "q": "Qual é o sentido do campo elétrico criado por uma carga puntiforme negativa?", "o": ["Apontando para a carga, de todas as direções.", "Saindo da carga, em todas as direções.", "Tangente a círculos ao redor da carga.", "Nulo, pois a carga é negativa."], "a": 0, "h": "O campo aponta no sentido da força sobre uma carga de prova positiva.", "e": "Uma carga de prova positiva é atraída por uma carga negativa. Assim, as linhas de campo chegam à carga.", "f": "camponeg", "x": {"1": "Para carga negativa, o campo entra na carga.", "2": "Isso seria um campo circular, que não é o caso.", "3": "O campo é não nulo: o sinal define o sentido."}, "an": "linhas_neg", "n": 1}, {"id": "q026", "t": "el", "q": "Qual é a unidade de carga elétrica no Sistema Internacional?", "o": ["Coulomb (C)", "Volt (V)", "Ampère (A)", "Newton (N)"], "a": 0, "h": "É a unidade ligada ao nome do físico da lei da força elétrica.", "e": "A carga elétrica é medida em coulombs. O volt mede tensão, o ampère mede corrente e o newton mede força.", "x": {"1": "Volt é unidade de potencial elétrico.", "2": "Ampère é unidade de corrente.", "3": "Newton é unidade de força."}, "n": 1}, {"id": "q027", "t": "el", "q": "Um eletroscópio de folhas está carregado positivamente. Um bastão negativo é aproximado do botão, sem tocar. O que acontece com as folhas?", "o": ["Se fecham um pouco, pois mais elétrons vão para elas.", "Se abrem mais, pois o bastão negativo adiciona prótons a elas.", "Ficam como estão, pois o bastão não toca o botão.", "Se abrem mais, pois o bastão atrai as cargas positivas para o botão."], "a": 0, "h": "O bastão negativo repele os elétrons livres do metal.", "e": "Os elétrons são empurrados do botão para as folhas, neutralizando parte da carga positiva delas. As folhas se aproximam.", "f": "eletroscopio", "x": {"1": "Prótons não são adicionados.", "2": "O bastão negativo repele elétrons para as folhas, influenciando-as sem tocar.", "3": "A indução afeta o eletroscópio: as folhas se fecham um pouco."}, "an": "eletroscopio_pos", "n": 2}, {"id": "q028", "an": "atrito_transfer", "t": "el", "q": "Verdadeiro ou falso: um corpo neutro não possui nenhuma carga elétrica.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Pense nos prótons e elétrons dentro de um corpo neutro.", "e": "Um corpo neutro tem cargas positivas e negativas em quantidades iguais. Elas se cancelam, mas existem.", "v": 1, "x": {"0": "Um corpo neutro tem cargas positivas e negativas em igual quantidade. A afirmação é falsa."}, "n": 1}, {"id": "q029", "an": "contato_div", "t": "el", "q": "Dois condutores idênticos, um carregado e outro neutro, entram em contato. O que determina a carga final de cada um?", "o": ["A carga total do sistema, dividida igualmente.", "Apenas o sinal do condutor que estava carregado.", "O material de que cada condutor é feito.", "O tempo em que os condutores ficam em contato."], "a": 0, "h": "Use a conservação da carga e a simetria entre os condutores idênticos.", "e": "Como são idênticos, a carga total se divide em partes iguais. O contato por mais tempo não muda o resultado.", "x": {"1": "O sinal não define a divisão.", "2": "Como são idênticos, o material não importa.", "3": "O tempo não altera o resultado após o equilíbrio."}, "n": 2}, {"id": "q030", "t": "eq", "q": "Qual é a função de um para-raios?", "o": ["Oferecer um caminho condutor até a terra para a descarga.", "Atrair os raios para longe da casa e acumular a carga.", "Gerar carga positiva para neutralizar as nuvens.", "Isolar o prédio, impedindo qualquer passagem de carga."], "a": 0, "h": "Pense no caminho que a carga encontra até o solo.", "e": "O para-raios é um condutor ligado à terra. A descarga passa por ele em vez de atingir a construção.", "x": {"1": "O para-raios não acumula carga: ele a conduz até a terra.", "2": "Ele não gera carga.", "3": "Ele não isola: conduz a descarga para a terra."}, "an": "pararaios", "n": 1}, {"id": "q031", "an": "inducao", "t": "el", "q": "Verdadeiro ou falso: na eletrização por indução, o corpo induzido nunca toca o indutor.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Lembre a diferença entre indução e contato.", "e": "Na indução o indutor apenas se aproxima. O induzido se carrega pela separação de cargas e pela ligação à terra, sem contato.", "v": 1, "x": {"1": "Na indução o corpo induzido não toca o indutor. A afirmação é verdadeira."}, "n": 1}, {"id": "q032", "t": "co", "q": "Dobrando o valor das duas cargas, sem mudar a distância, a força elétrica entre elas:", "o": ["Fica 4 vezes maior.", "Fica 2 vezes maior.", "Fica 8 vezes maior.", "Não se altera."], "a": 0, "h": "A força depende do produto das duas cargas.", "e": "F ∝ q₁·q₂. Dobrando as duas, o produto passa a 2 × 2 = 4 vezes o valor inicial.", "x": {"1": "F ∝ q₁·q₂: dobrando as duas cargas, multiplica por 2·2 = 4, não por 2.", "2": "8 seria dobrar três grandezas.", "3": "A força depende das cargas."}, "an": "coul_qq2", "n": 2}, {"id": "q033", "an": "calc_q033", "t": "ca", "q": "Qual é a intensidade do campo elétrico a 0,3 m de uma carga puntiforme de +2 µC, no vácuo? (k = 9 × 10⁹ N·m²/C²)", "o": ["2 × 10⁵ N/C", "6 × 10⁴ N/C", "2 × 10⁴ N/C", "6 × 10⁵ N/C"], "a": 0, "h": "Use E = k·Q / d².", "e": "E = 9 × 10⁹ × 2 × 10⁻⁶ / (0,3)² = 1,8 × 10⁴ / 0,09 = 2 × 10⁵ N/C.", "c": 1, "x": {"1": "6 × 10⁴ usa d no lugar de d².", "2": "2 × 10⁴ erra o expoente.", "3": "6 × 10⁵ erra o expoente e usa d no lugar de d²."}, "n": 2}, {"id": "q034", "t": "ca", "q": "Em um campo elétrico uniforme, uma carga negativa fica sujeita a uma força:", "o": ["No sentido contrário ao do campo.", "No mesmo sentido do campo.", "Perpendicular ao campo.", "Nula, pois a carga é negativa."], "a": 0, "h": "Use F = q·E e observe o sinal de q.", "e": "F = qE. Com q negativa, a força tem sentido oposto ao do campo.", "f": "placas", "x": {"1": "A carga negativa sofre força oposta ao campo.", "2": "A força é paralela ao campo.", "3": "A força existe e é não nula."}, "an": "unif_neg", "n": 2}, {"id": "q035", "an": "linhas_cruz", "t": "ca", "q": "Verdadeiro ou falso: duas linhas de campo elétrico podem se cruzar.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Em cada ponto, o campo tem uma única direção e um único sentido.", "e": "Se as linhas se cruzassem, haveria duas direções de campo no mesmo ponto, o que é impossível.", "v": 1, "x": {"0": "Linhas de campo não se cruzam, pois em cada ponto o campo tem uma só direção. A afirmação é falsa."}, "n": 1}, {"id": "q036", "t": "po", "q": "Qual é a unidade de potencial elétrico no SI?", "o": ["Volt (V)", "Joule (J)", "Coulomb (C)", "Watt (W)"], "a": 0, "h": "É energia dividida por carga.", "e": "O potencial elétrico é energia por unidade de carga: 1 V = 1 J/C.", "x": {"1": "Joule é unidade de energia.", "2": "Coulomb é unidade de carga.", "3": "Watt é unidade de potência."}, "n": 1}, {"id": "q037", "an": "calc_q037", "t": "po", "q": "Qual é o potencial elétrico a 2 m de uma carga de +4 µC, no vácuo? (k = 9 × 10⁹ N·m²/C²)", "o": ["1,8 × 10⁴ V", "3,6 × 10⁴ V", "9 × 10³ V", "1,8 × 10⁻² V"], "a": 0, "h": "Use V = k·Q / d, sem elevar a distância ao quadrado.", "e": "V = 9 × 10⁹ × 4 × 10⁻⁶ / 2 = 1,8 × 10⁴ V.", "c": 1, "x": {"1": "3,6 × 10⁴ V usa d = 1 m em vez de 2 m.", "2": "9 × 10³ V usa d².", "3": "1,8 × 10⁻² V erra o sinal do expoente."}, "n": 2}, {"id": "q038", "an": "calc_q038", "t": "po", "q": "Uma carga de 2 µC se desloca entre dois pontos com diferença de potencial de 100 V. Qual é o trabalho da força elétrica?", "o": ["2 × 10⁻⁴ J", "2 × 10⁻⁸ J", "5 × 10⁻⁷ J", "2 × 10² J"], "a": 0, "h": "Use W = q·U, com a carga em coulombs.", "e": "W = q·U = 2 × 10⁻⁶ × 100 = 2 × 10⁻⁴ J.", "c": 1, "x": {"1": "2 × 10⁻⁸ J divide por 100 em vez de multiplicar.", "2": "5 × 10⁻⁷ J não vem de W = q·ΔV.", "3": "2 × 10² J esquece a conversão de µC."}, "n": 2}, {"id": "q039", "an": "equip", "t": "po", "q": "Ao longo de uma superfície equipotencial, o trabalho da força elétrica para deslocar uma carga é:", "o": ["Nulo.", "Máximo.", "Positivo e constante.", "Negativo e constante."], "a": 0, "h": "Pense na diferença de potencial entre os pontos da superfície.", "e": "Entre pontos de mesmo potencial U = 0, então W = qU = 0. As linhas de campo são perpendiculares à superfície equipotencial.", "f": "equip", "x": {"1": "Em uma equipotencial a diferença de potencial é zero, então o trabalho é zero.", "2": "O trabalho não é máximo.", "3": "O trabalho é nulo, não positivo."}, "n": 2}, {"id": "q040", "an": "pos_livre", "t": "po", "q": "Verdadeiro ou falso: uma carga positiva abandonada em repouso em um campo elétrico tende a ir para pontos de menor potencial.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Pense em uma bola solta em uma rampa: ela busca menor energia potencial.", "e": "Cargas positivas se deslocam espontaneamente para potenciais menores, no sentido do campo. Cargas negativas vão para potenciais maiores.", "v": 1, "x": {"1": "Uma carga positiva tende a ir para menores potenciais. A afirmação é verdadeira."}, "n": 1}, {"id": "q041", "an": "gaiola", "t": "eq", "q": "No interior de um condutor em equilíbrio eletrostático, o campo elétrico é:", "o": ["Nulo.", "Máximo no centro.", "Igual ao da superfície.", "Radial e voltado para dentro."], "a": 0, "h": "Em equilíbrio, as cargas livres não se movem.", "e": "Se o campo não fosse nulo, as cargas livres se moveriam. Em equilíbrio, o campo resultante no interior é zero.", "x": {"1": "O campo no interior é nulo em todos os pontos, inclusive no centro.", "2": "O campo na superfície não é nulo, mas o interior sim.", "3": "Um campo radial para dentro exigiria cargas dentro do condutor, que não existem em equilíbrio."}, "n": 1}, {"id": "q042", "t": "eq", "q": "Onde ficam as cargas em excesso de um condutor isolado em equilíbrio eletrostático?", "o": ["Na superfície externa.", "Distribuídas por todo o volume.", "Concentradas no centro.", "Na superfície interna de uma cavidade."], "a": 0, "h": "As cargas de mesmo sinal se repelem e se afastam ao máximo.", "e": "A repulsão leva as cargas para o mais longe possível umas das outras: a superfície externa.", "x": {"1": "As cargas em excesso ficam na superfície, não no volume.", "2": "Elas se afastam o máximo possível, e não se concentram no centro.", "3": "Em uma cavidade vazia, a superfície interna não tem carga."}, "an": "superf", "n": 1}, {"id": "q043", "an": "gaiola", "t": "eq", "q": "Verdadeiro ou falso: dentro de um carro de carroceria metálica, as pessoas ficam protegidas de uma descarga atmosférica.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Lembre a gaiola de Faraday.", "e": "A carroceria funciona como uma gaiola de Faraday: a carga escoa pela superfície externa, e o campo no interior é praticamente nulo.", "v": 1, "x": {"1": "A carroceria metálica forma uma gaiola de Faraday, e o interior fica protegido. A afirmação é verdadeira."}, "n": 1}, {"id": "q044", "t": "eq", "q": "Em um condutor carregado em equilíbrio, o campo elétrico é mais intenso:", "o": ["Nas regiões pontiagudas.", "Nas regiões planas.", "No interior do condutor.", "Nas regiões côncavas."], "a": 0, "h": "Pense no formato da ponta de um para-raios.", "e": "É o poder das pontas: a densidade de cargas é maior nas regiões pontiagudas, e ali o campo é mais intenso.", "x": {"1": "Nas regiões planas o campo é menos intenso.", "2": "No interior do condutor o campo é nulo.", "3": "Nas regiões côncavas o campo é fraco."}, "an": "pontas", "n": 2}, {"id": "q045", "an": "pot_cond", "t": "eq", "q": "O potencial elétrico em todos os pontos de um condutor em equilíbrio eletrostático é:", "o": ["O mesmo em todos os pontos.", "Maior no centro.", "Maior nas pontas.", "Nulo na superfície."], "a": 0, "h": "Se houvesse diferença de potencial, as cargas se moveriam.", "e": "Com campo nulo no interior e a superfície equipotencial, todo o condutor tem o mesmo potencial.", "x": {"1": "O potencial é igual em todo o condutor, inclusive no centro.", "2": "O potencial é igual nas pontas e no resto. O campo é que é mais forte nelas.", "3": "O potencial pode ser diferente de zero, pois depende da carga e da referência."}, "n": 2}, {"id": "q046", "an": "calc_q046", "t": "el", "q": "Um bastão de vidro atritado com seda fica com +3,2 × 10⁻⁹ C. Quantos elétrons ele perdeu? (e = 1,6 × 10⁻¹⁹ C)", "o": ["2 × 10¹⁰", "5 × 10¹⁰", "2 × 10⁻¹⁰", "1,6 × 10¹⁰"], "a": 0, "h": "Use n = Q / e.", "e": "n = 3,2 × 10⁻⁹ / 1,6 × 10⁻¹⁹ = 2 × 10¹⁰ elétrons.", "c": 1, "x": {"1": "5 × 10¹⁰ inverteu a divisão.", "2": "O expoente está errado: o número de elétrons é muito grande.", "3": "1,6 × 10¹⁰ não vem da divisão 3,2 × 10⁻⁹ / 1,6 × 10⁻¹⁹."}, "n": 2}, {"id": "q047", "t": "el", "q": "Qual é o valor da carga elementar?", "o": ["1,6 × 10⁻¹⁹ C", "1,6 × 10¹⁹ C", "9 × 10⁹ C", "3 × 10⁸ C"], "a": 0, "h": "É a carga de um próton, em módulo.", "e": "A carga elementar é e = 1,6 × 10⁻¹⁹ C, a menor carga livre observada.", "x": {"1": "O expoente deve ser negativo: a carga elementar é muito pequena.", "2": "9 × 10⁹ é a constante k de Coulomb.", "3": "3 × 10⁸ é a velocidade da luz em m/s."}, "n": 1}, {"id": "q048", "t": "el", "q": "Verdadeiro ou falso: um corpo pode ter carga igual a 0,8 vez a carga de um elétron.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "A carga é quantizada.", "e": "A carga de um corpo é sempre múltiplo inteiro de e (Q = n·e).", "v": 1, "x": {"0": "A carga é quantizada: só aparece em múltiplos inteiros de e. A afirmação é falsa."}, "n": 1}, {"id": "q049", "an": "calc_q049", "t": "el", "q": "Qual é a carga de um corpo que ganhou 10¹² elétrons? (e = 1,6 × 10⁻¹⁹ C)", "o": ["−1,6 × 10⁻⁷ C", "+1,6 × 10⁻⁷ C", "−1,6 × 10⁻³¹ C", "+1,6 × 10⁻³¹ C"], "a": 0, "h": "Ganhar elétrons deixa o corpo negativo.", "e": "|Q| = 10¹² × 1,6 × 10⁻¹⁹ = 1,6 × 10⁻⁷ C, com sinal negativo.", "c": 1, "x": {"1": "Elétrons ganhos dão carga negativa.", "2": "O expoente: 10¹² · 1,6 × 10⁻¹⁹ = 1,6 × 10⁻⁷, e não −31.", "3": "O sinal é negativo, e o expoente não é −31."}, "n": 2}, {"id": "q050", "an": "cond_isol", "t": "el", "q": "Qual dos materiais abaixo é isolante?", "o": ["Borracha", "Cobre", "Alumínio", "Água salgada"], "a": 0, "h": "Isolantes quase não têm elétrons livres.", "e": "A borracha é isolante. Cobre e alumínio são metais, e a água salgada conduz por íons.", "x": {"1": "Cobre é bom condutor.", "2": "Alumínio é bom condutor.", "3": "A água salgada conduz por causa dos íons."}, "n": 1}, {"id": "q051", "an": "calc_q051", "t": "el", "q": "A esfera A (+8 µC) toca a esfera B, neutra e idêntica, e depois são separadas. Qual é a carga de B?", "o": ["+4 µC", "+8 µC", "0", "−4 µC"], "a": 0, "h": "A carga total se divide igualmente.", "e": "Esferas idênticas dividem +8 µC em partes iguais: +4 µC cada.", "c": 1, "x": {"1": "+8 µC seria a carga de A antes do contato.", "2": "B recebe carga no contato, então não fica neutra.", "3": "O sinal está errado: a carga total é positiva."}, "n": 2}, {"id": "q052", "t": "el", "q": "Duas esferas idênticas, com +5 µC e −1 µC, são postas em contato. Qual é a carga final de cada uma?", "o": ["+2 µC", "+3 µC", "+4 µC", "−2 µC"], "a": 0, "h": "Some as cargas com sinal e divida por dois.", "e": "(+5 − 1)/2 = +2 µC em cada esfera.", "c": 1, "x": {"1": "+3 µC não divide a carga total corretamente: (5 − 1)/2 = 2.", "2": "+4 µC é a soma 5 − 1 sem dividir por 2.", "3": "O sinal está errado: a soma é positiva."}, "an": "contato_q052", "n": 2}, {"id": "q053", "an": "pente_papel", "t": "el", "q": "Ao pentear o cabelo seco, um pente de plástico passa a atrair pedacinhos de papel. Isso mostra que o pente:", "o": ["Foi eletrizado por atrito.", "Virou um ímã.", "Ficou neutro e atrai por gravidade.", "Perdeu todos os seus prótons."], "a": 0, "h": "Pense no atrito entre o pente e o cabelo.", "e": "O atrito eletriza o pente, que então atrai o papel por polarização.", "x": {"1": "O pente não é ímã; a atração é elétrica.", "2": "A gravidade é desprezível aqui.", "3": "Prótons não saem do átomo."}, "n": 2}, {"id": "q054", "an": "inducao", "t": "el", "q": "Quais processos exigem que um dos corpos já esteja carregado antes?", "o": ["Contato e indução", "Atrito e contato", "Somente o atrito", "Atrito e indução"], "a": 0, "h": "No atrito, os dois corpos podem começar neutros.", "e": "Contato e indução precisam de um corpo previamente carregado. O atrito pode eletrizar dois corpos neutros.", "x": {"1": "No atrito os corpos podem começar neutros.", "2": "No atrito não é preciso carga prévia.", "3": "No atrito não é preciso carga prévia, e a indução exige um corpo carregado."}, "n": 1}, {"id": "q055", "an": "contato_neg", "t": "el", "q": "O contato entre um corpo negativo e um corpo neutro deixa o corpo neutro:", "o": ["Negativo", "Positivo", "Neutro", "Positivo e negativo ao mesmo tempo"], "a": 0, "h": "O corpo neutro adquire o sinal do outro.", "e": "Elétrons passam do corpo negativo para o neutro, que fica negativo.", "x": {"1": "O corpo neutro recebe elétrons e fica negativo.", "2": "Ele recebe carga e deixa de ser neutro.", "3": "O corpo fica com um único sinal, e não com os dois."}, "n": 1}, {"id": "q056", "an": "cond_isol", "t": "el", "q": "Qual é a principal diferença entre condutores e isolantes?", "o": ["Condutores têm elétrons livres para se mover.", "Isolantes não têm elétrons.", "Condutores não têm prótons.", "Isolantes são sempre negativos."], "a": 0, "h": "Pense na mobilidade das cargas.", "e": "Nos condutores há elétrons livres. Nos isolantes, os elétrons ficam presos aos átomos.", "x": {"1": "Isolantes têm elétrons, só que presos aos átomos.", "2": "Condutores têm prótons como qualquer matéria.", "3": "Isolantes podem ser neutros, positivos ou negativos."}, "n": 1}, {"id": "q057", "an": "atrito_transfer", "t": "el", "q": "Verdadeiro ou falso: se um corpo neutro perde elétrons, ele fica com carga positiva.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Falta de elétrons deixa prótons em excesso.", "e": "Ao perder elétrons, os prótons passam a predominar e o corpo fica positivo.", "v": 1, "x": {"1": "Perder elétrons deixa o corpo com excesso de prótons, ou seja, positivo. A afirmação é verdadeira."}, "n": 1}, {"id": "q058", "an": "calc_q058", "t": "el", "q": "Um corpo tem carga de +4,8 × 10⁻⁶ C. Quantos elétrons ele perdeu? (e = 1,6 × 10⁻¹⁹ C)", "o": ["3 × 10¹³", "7,7 × 10¹³", "3 × 10⁻¹³", "1,2 × 10¹³"], "a": 0, "h": "Use n = Q / e.", "e": "n = 4,8 × 10⁻⁶ / 1,6 × 10⁻¹⁹ = 3 × 10¹³ elétrons.", "c": 1, "x": {"1": "7,7 × 10¹³ não vem da divisão correta.", "2": "O expoente tem sinal errado.", "3": "1,2 × 10¹³ não vem da divisão correta."}, "n": 2}, {"id": "q059", "an": "atrito_transfer", "t": "el", "q": "Dois corpos neutros são atritados. Qual afirmação sobre as cargas finais é correta?", "o": ["A soma das cargas continua sendo zero.", "A soma das cargas passa a ser positiva.", "Os dois corpos ficam com o mesmo sinal.", "A soma das cargas passa a ser negativa."], "a": 0, "h": "Pense na conservação da carga.", "e": "A carga total inicial era nula e se conserva. Um corpo fica positivo e o outro, negativo, com valores iguais.", "x": {"1": "A soma das cargas se conserva em zero.", "2": "Eles ficam com sinais opostos.", "3": "A soma permanece zero, não negativa."}, "n": 2}, {"id": "q060", "an": "contato_pos", "t": "el", "q": "Uma esfera metálica neutra e isolada é tocada por um bastão positivo. Ela fica:", "o": ["Positiva.", "Negativa.", "Neutra.", "Com um lado positivo e outro negativo, sem carga total."], "a": 0, "h": "No contato, o sinal final é o do corpo que tocou.", "e": "Elétrons passam da esfera para o bastão positivo. A esfera fica positiva.", "x": {"1": "Ao tocar um bastão positivo, a esfera cede elétrons e fica positiva.", "2": "Ela recebe carga, então deixa de ser neutra.", "3": "Isso descreve a indução (polarização), não o contato."}, "n": 1}, {"id": "q061", "an": "atrito_transfer", "t": "el", "q": "Qual é um exemplo de eletrização por atrito?", "o": ["Uma régua de plástico esfregada no cabelo.", "Uma esfera tocando outra carregada.", "Um bastão aproximado de uma esfera ligada à terra.", "Uma pilha ligada a uma lâmpada."], "a": 0, "h": "Procure dois materiais sendo esfregados.", "e": "Esfregar dois materiais diferentes provoca troca de elétrons. As outras opções são contato, indução e corrente.", "x": {"1": "Isso é contato.", "2": "Isso é indução.", "3": "Isso é um circuito elétrico, não eletrização."}, "n": 1}, {"id": "q062", "t": "co", "q": "Duas cargas de mesmo sinal se repelem com força F. Se uma delas for dobrada, a nova força será:", "o": ["2F", "F/2", "4F", "F"], "a": 0, "h": "A força é proporcional ao produto das cargas.", "e": "F ∝ q₁·q₂. Dobrando só uma carga, a força dobra.", "x": {"1": "F/2 reduziria a força, mas dobrar uma carga a aumenta.", "2": "4F exigiria dobrar as duas cargas.", "3": "F não muda só se as cargas não mudarem."}, "an": "coul_q2", "n": 2}, {"id": "q063", "t": "co", "q": "Reduzindo à metade a distância entre duas cargas, a força entre elas:", "o": ["Fica 4 vezes maior.", "Fica 2 vezes maior.", "Fica 2 vezes menor.", "Fica 4 vezes menor."], "a": 0, "h": "Lembre que d aparece ao quadrado.", "e": "F ∝ 1/d². Com d/2, a força fica 1/(1/2)² = 4 vezes maior.", "x": {"1": "2 vezes maior vem de uma relação 1/d.", "2": "A força aumenta, não diminui.", "3": "A força aumenta ao diminuir a distância."}, "an": "coul_d05", "n": 2}, {"id": "q064", "an": "calc_q064", "t": "co", "q": "Duas cargas de +1 µC e −1 µC estão a 0,1 m no vácuo. Qual é a força entre elas? (k = 9 × 10⁹ N·m²/C²)", "o": ["0,9 N", "9 N", "0,09 N", "90 N"], "a": 0, "h": "Use F = k·|q₁·q₂| / d².", "e": "F = 9 × 10⁹ × 10⁻⁶ × 10⁻⁶ / (0,1)² = 0,9 N, de atração.", "c": 1, "x": {"1": "9 N tem fator 10 a mais.", "2": "0,09 N tem fator 10 a menos.", "3": "90 N tem fator 100 a mais."}, "n": 2}, {"id": "q065", "an": "par_forcas", "t": "co", "q": "Duas cargas de sinais opostos exercem entre si forças de:", "o": ["Atração, com o mesmo módulo nas duas.", "Repulsão, com o mesmo módulo nas duas.", "Atração, só sobre a carga menor.", "Repulsão, só sobre a carga maior."], "a": 0, "h": "Cargas opostas e a terceira lei de Newton.", "e": "Cargas opostas se atraem, e as forças formam um par de ação e reação.", "x": {"1": "Cargas opostas se atraem.", "2": "A força atua nas duas cargas.", "3": "Cargas opostas se atraem, e as duas sofrem força."}, "n": 1}, {"id": "q066", "t": "co", "q": "A constante k da lei de Coulomb, no vácuo, vale aproximadamente:", "o": ["9 × 10⁹ N·m²/C²", "9 × 10⁻⁹ N·m²/C²", "1,6 × 10⁻¹⁹ N·m²/C²", "3 × 10⁸ N·m²/C²"], "a": 0, "h": "É um número muito grande.", "e": "k ≈ 9 × 10⁹ N·m²/C². 1,6 × 10⁻¹⁹ C é a carga elementar, e 3 × 10⁸ m/s é a velocidade da luz.", "x": {"1": "O expoente é positivo: k é grande.", "2": "1,6 × 10⁻¹⁹ é a carga elementar, em C.", "3": "3 × 10⁸ é a velocidade da luz."}, "n": 1}, {"id": "q067", "an": "calc_q067", "t": "co", "q": "Duas cargas de +2 µC cada estão a 0,6 m. Qual é a força de repulsão entre elas? (k = 9 × 10⁹ N·m²/C²)", "o": ["0,1 N", "0,01 N", "1 N", "0,2 N"], "a": 0, "h": "Use F = k·q₁·q₂ / d².", "e": "F = 9 × 10⁹ × 4 × 10⁻¹² / 0,36 = 3,6 × 10⁻² / 0,36 = 0,1 N.", "c": 1, "x": {"1": "0,01 N tem fator 10 a menos.", "2": "1 N tem fator 10 a mais.", "3": "0,2 N não vem de k·q²/d²."}, "n": 2}, {"id": "q068", "an": "coul_grafico", "t": "co", "q": "Verdadeiro ou falso: a força elétrica entre duas cargas aumenta quando a distância entre elas aumenta.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "A distância fica no denominador.", "e": "F ∝ 1/d². Quanto maior a distância, menor a força.", "v": 1, "x": {"0": "A força diminui com a distância. A afirmação é falsa."}, "n": 1}, {"id": "q069", "t": "co", "q": "A força elétrica entre duas cargas pontuais depende:", "o": ["Do produto das cargas e do inverso do quadrado da distância.", "Da soma das cargas e do inverso da distância.", "Somente do sinal das cargas.", "Do quadrado da distância, aumentando com ela."], "a": 0, "h": "Lembre a fórmula de Coulomb.", "e": "F = k·|q₁·q₂| / d²: proporcional ao produto das cargas e inversamente proporcional ao quadrado da distância.", "x": {"1": "A força depende do produto das cargas e de 1/d².", "2": "O sinal define atração ou repulsão, mas a intensidade depende das cargas e da distância.", "3": "A força diminui com o aumento da distância."}, "n": 1}, {"id": "q070", "t": "co", "q": "Três cargas positivas iguais estão alinhadas, e a carga B fica no meio, à mesma distância de A e de C. A força resultante sobre B é:", "o": ["Nula.", "Para o lado de A.", "Para o lado de C.", "Perpendicular à linha das cargas."], "a": 0, "h": "Desenhe as duas forças que atuam sobre B.", "e": "A repele B para um lado e C repele B para o outro, com o mesmo módulo. As forças se cancelam.", "x": {"1": "As forças de A e C têm o mesmo módulo e sentidos opostos.", "2": "Mesmo raciocínio: as forças se anulam.", "3": "As forças estão na linha das cargas."}, "an": "forca_fb", "n": 3}, {"id": "q071", "t": "co", "q": "Duas cargas se repelem com força F. Se a distância e uma das cargas forem multiplicadas por 2, a nova força será:", "o": ["F/2", "F/4", "2F", "F"], "a": 0, "h": "Multiplique os efeitos: um para a carga e outro para a distância.", "e": "A carga dobrada multiplica a força por 2, e a distância dobrada divide por 4: F' = 2F/4 = F/2.", "x": {"1": "F/4 vem de só dobrar a distância.", "2": "2F vem de só dobrar a carga.", "3": "As duas mudanças não se cancelam: o resultado é F/2."}, "an": "coul_d2q2", "n": 3}, {"id": "q072", "t": "ca", "q": "Qual é a direção do campo elétrico de uma carga puntiforme positiva?", "o": ["Radial, afastando-se da carga.", "Radial, aproximando-se da carga.", "Tangente a círculos em torno da carga.", "Paralela a uma direção fixa."], "a": 0, "h": "Pense na força sobre uma carga de prova positiva.", "e": "A carga de prova positiva é repelida. O campo sai da carga em todas as direções.", "f": "campopos", "x": {"1": "Para carga positiva, o campo sai da carga.", "2": "O campo é radial, não circular.", "3": "O campo muda de direção em cada ponto."}, "an": "linhas_pos", "n": 1}, {"id": "q073", "an": "calc_q073", "t": "ca", "q": "Uma carga de 2 µC está em um campo de 3 × 10⁵ N/C. Qual é a força sobre ela?", "o": ["0,6 N", "6 N", "0,06 N", "1,5 × 10¹¹ N"], "a": 0, "h": "Use F = q·E, com q em coulombs.", "e": "F = 2 × 10⁻⁶ × 3 × 10⁵ = 0,6 N.", "c": 1, "x": {"1": "6 N tem fator 10 a mais.", "2": "0,06 N tem fator 10 a menos.", "3": "1,5 × 10¹¹ vem de dividir E por q."}, "n": 2}, {"id": "q074", "an": "campo_dist", "t": "ca", "q": "Se a distância a uma carga puntiforme dobra, o módulo do campo elétrico:", "o": ["Fica 4 vezes menor.", "Fica 2 vezes menor.", "Fica 2 vezes maior.", "Fica 4 vezes maior."], "a": 0, "h": "Use E = k·Q / d².", "e": "E ∝ 1/d². Dobrando d, o campo cai à quarta parte.", "x": {"1": "Como E ∝ 1/d², dobrar d reduz E 4 vezes.", "2": "Dobrar a distância reduz o campo.", "3": "Dobrar a distância reduz o campo."}, "n": 2}, {"id": "q075", "t": "ca", "q": "Verdadeiro ou falso: o campo elétrico é uma grandeza vetorial.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Ele tem módulo, direção e sentido?", "e": "O campo elétrico é vetorial: tem módulo, direção e sentido.", "v": 1, "x": {"1": "O campo tem módulo, direção e sentido. A afirmação é verdadeira."}, "n": 1}, {"id": "q076", "an": "linhas_cruz", "t": "ca", "q": "Onde as linhas de campo ficam mais próximas umas das outras?", "o": ["Onde o campo é mais intenso.", "Onde o campo é mais fraco.", "Onde o potencial é nulo.", "Somente perto de cargas negativas."], "a": 0, "h": "A densidade de linhas indica a intensidade do campo.", "e": "A densidade de linhas de campo é proporcional à intensidade do campo.", "x": {"1": "Linhas mais próximas indicam campo mais forte.", "2": "O potencial não define a densidade de linhas.", "3": "Vale para qualquer carga."}, "n": 1}, {"id": "q077", "an": "calc_q077", "t": "ca", "q": "Qual é o campo elétrico a 1 m de uma carga de +1 µC? (k = 9 × 10⁹ N·m²/C²)", "o": ["9 × 10³ N/C", "9 × 10⁹ N/C", "9 × 10⁻³ N/C", "9 × 10⁶ N/C"], "a": 0, "h": "Use E = k·Q / d².", "e": "E = 9 × 10⁹ × 10⁻⁶ / 1² = 9 × 10³ N/C.", "c": 1, "x": {"1": "9 × 10⁹ N/C esquece o fator µ = 10⁻⁶.", "2": "9 × 10⁻³ erra o sinal do expoente.", "3": "9 × 10⁶ converteu µ só uma vez por 10⁻³."}, "n": 2}, {"id": "q078", "t": "ca", "q": "As linhas de campo elétrico de uma carga positiva isolada:", "o": ["Saem da carga.", "Chegam à carga.", "Formam círculos fechados.", "Não existem."], "a": 0, "h": "Uma carga de prova positiva é repelida.", "e": "Por convenção, as linhas saem das cargas positivas e chegam às negativas.", "x": {"1": "Para carga positiva, as linhas saem.", "2": "Linhas de campo eletrostático não são fechadas.", "3": "As linhas existem como representação do campo."}, "an": "linhas_pos", "n": 1}, {"id": "q079", "t": "ca", "q": "Verdadeiro ou falso: em um campo elétrico uniforme, a força sobre uma carga de prova tem o mesmo valor em qualquer ponto.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Uniforme significa que o campo é o mesmo em todos os pontos.", "e": "Com E constante, F = qE também é constante, desde que q não mude.", "v": 1, "x": {"1": "O campo é uniforme, então a força é a mesma. A afirmação é verdadeira."}, "an": "placas", "n": 1}, {"id": "q080", "an": "calc_q080", "t": "ca", "q": "Uma carga de prova de −1 µC sofre uma força de 4 N para o leste. O campo no ponto tem módulo e sentido:", "o": ["4 × 10⁶ N/C, para o oeste", "4 × 10⁶ N/C, para o leste", "4 × 10⁻⁶ N/C, para o oeste", "4 × 10⁻⁶ N/C, para o leste"], "a": 0, "h": "O campo só tem o sentido da força se a carga for positiva.", "e": "E = F/|q| = 4 / 10⁻⁶ = 4 × 10⁶ N/C. Como q é negativa, o campo aponta contra a força: oeste.", "c": 1, "x": {"1": "Para carga negativa, o campo tem sentido oposto ao da força.", "2": "O expoente está errado.", "3": "O expoente e o sentido estão errados."}, "n": 2}, {"id": "q081", "t": "ca", "q": "Entre duas placas paralelas, planas e próximas, com cargas opostas, o campo elétrico é aproximadamente:", "o": ["Uniforme.", "Nulo.", "Radial.", "Crescente em direção às bordas."], "a": 0, "h": "Pense em linhas paralelas e igualmente espaçadas.", "e": "Entre placas planas e próximas, as linhas de campo são retas, paralelas e igualmente espaçadas.", "f": "placas", "x": {"1": "Entre placas paralelas, o campo é praticamente constante, não nulo.", "2": "O campo é paralelo, e não radial como no caso de uma carga pontual.", "3": "O campo só varia perto das bordas, e não cresce em direção a elas."}, "an": "placas", "n": 1}, {"id": "q082", "t": "ca", "q": "Duas cargas iguais e positivas estão separadas por uma distância d. No ponto médio entre elas, o campo elétrico resultante é:", "o": ["Nulo.", "Dirigido para uma das cargas.", "O dobro do campo de uma carga.", "Perpendicular à linha das cargas."], "a": 0, "h": "Some os dois vetores campo no ponto médio.", "e": "No ponto médio, os dois campos têm o mesmo módulo e sentidos opostos. Eles se cancelam.", "x": {"1": "As duas cargas são iguais, então os campos se cancelam no ponto médio.", "2": "Os campos têm sentidos opostos e se anulam, não se somam.", "3": "Os campos estão na linha das cargas, não perpendiculares a ela."}, "an": "campo_pp", "n": 2}, {"id": "q083", "an": "pot_energia_igual", "t": "po", "q": "A energia potencial elétrica de duas cargas de mesmo sinal, quando elas se aproximam:", "o": ["Aumenta.", "Diminui.", "Não muda.", "Fica nula."], "a": 0, "h": "Aproximar cargas que se repelem exige trabalho externo.", "e": "Aproximar cargas de mesmo sinal exige trabalho externo, que fica armazenado como energia potencial.", "x": {"1": "Aproximar cargas de mesmo sinal exige trabalho, então a energia aumenta.", "2": "A energia varia com a distância.", "3": "A energia só seria nula a distância infinita."}, "n": 2}, {"id": "q084", "an": "calc_q084", "t": "po", "q": "Qual é o potencial elétrico a 3 m de uma carga de −6 µC, no vácuo? (k = 9 × 10⁹ N·m²/C²)", "o": ["−1,8 × 10⁴ V", "+1,8 × 10⁴ V", "−5,4 × 10⁴ V", "−6 × 10³ V"], "a": 0, "h": "O sinal do potencial acompanha o sinal da carga.", "e": "V = kQ/d = 9 × 10⁹ × (−6 × 10⁻⁶) / 3 = −1,8 × 10⁴ V.", "c": 1, "x": {"1": "O sinal da carga negativa dá potencial negativo.", "2": "−5,4 × 10⁴ V usa d = 1 m.", "3": "−6 × 10³ V usa d² no denominador."}, "n": 2}, {"id": "q085", "an": "calc_q085", "t": "po", "q": "Uma carga de 5 µC é levada de um ponto a 20 V para outro a 120 V. Qual é a variação da energia potencial?", "o": ["5 × 10⁻⁴ J", "5 × 10⁻⁶ J", "6 × 10⁻⁴ J", "1,2 × 10⁻³ J"], "a": 0, "h": "Use ΔEp = q·ΔV.", "e": "ΔEp = 5 × 10⁻⁶ × (120 − 20) = 5 × 10⁻⁴ J.", "c": 1, "x": {"1": "5 × 10⁻⁶ J não usa ΔV = 100 V.", "2": "6 × 10⁻⁴ J usa só o potencial final de 120 V.", "3": "1,2 × 10⁻³ J não vem de q·ΔV."}, "n": 2}, {"id": "q086", "an": "pot_soma", "t": "po", "q": "Verdadeiro ou falso: o potencial elétrico é uma grandeza escalar.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Ele só tem valor, sem direção.", "e": "O potencial é escalar. Potenciais de várias cargas se somam algebricamente.", "v": 1, "x": {"1": "O potencial é uma grandeza escalar, sem direção. A afirmação é verdadeira."}, "n": 1}, {"id": "q087", "an": "pot_soma", "t": "po", "q": "O potencial gerado por duas cargas puntiformes em um ponto é:", "o": ["A soma algébrica dos potenciais de cada carga.", "A soma vetorial dos potenciais.", "O maior dos dois potenciais.", "O produto dos potenciais."], "a": 0, "h": "O potencial é escalar.", "e": "Como o potencial é escalar, somam-se os valores com seus sinais.", "x": {"1": "O potencial é escalar, então a soma é algébrica, e não vetorial.", "2": "O potencial total é a soma, não o maior valor.", "3": "Soma-se, e não se multiplica."}, "n": 2}, {"id": "q088", "t": "po", "q": "Um elétron parte do repouso e é acelerado por uma diferença de potencial de 100 V. Que energia cinética ele ganha? (e = 1,6 × 10⁻¹⁹ C)", "o": ["1,6 × 10⁻¹⁷ J", "1,6 × 10⁻²¹ J", "1,6 × 10⁻¹⁹ J", "1,6 × 10⁻¹⁵ J"], "a": 0, "h": "Use Ec = |q|·U.", "e": "O trabalho da força elétrica vira energia cinética: Ec = 1,6 × 10⁻¹⁹ × 100 = 1,6 × 10⁻¹⁷ J.", "c": 1, "x": {"1": "1,6 × 10⁻²¹ J divide por 100.", "2": "1,6 × 10⁻¹⁹ J usa ΔV = 1 V.", "3": "1,6 × 10⁻¹⁵ J usa ΔV = 10⁴ V."}, "an": "acel_e", "n": 2}, {"id": "q089", "an": "calc_q089", "t": "po", "q": "Em um campo uniforme de 200 V/m, qual é a diferença de potencial entre dois pontos separados por 0,5 m ao longo do campo?", "o": ["100 V", "400 V", "10 V", "1000 V"], "a": 0, "h": "Use U = E·d.", "e": "U = E·d = 200 × 0,5 = 100 V.", "c": 1, "x": {"1": "400 V divide E por d em vez de multiplicar.", "2": "10 V não vem de E·d.", "3": "1000 V erra o cálculo E·d."}, "n": 2}, {"id": "q090", "t": "po", "q": "Uma carga positiva se desloca no sentido do campo elétrico. O potencial:", "o": ["Diminui.", "Aumenta.", "Permanece constante.", "Fica nulo."], "a": 0, "h": "O campo aponta de potenciais maiores para menores.", "e": "O campo aponta no sentido dos potenciais decrescentes. Ao seguir o campo, o potencial diminui.", "x": {"1": "O potencial diminui no sentido do campo.", "2": "Ele varia ao longo do campo.", "3": "O potencial não é nulo."}, "an": "unif_pos", "n": 2}, {"id": "q091", "t": "po", "q": "Verdadeiro ou falso: o trabalho da força elétrica entre dois pontos depende do caminho percorrido.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "A força elétrica é conservativa.", "e": "A força elétrica é conservativa. O trabalho depende só dos pontos inicial e final.", "v": 1, "x": {"0": "A força elétrica é conservativa, então o trabalho não depende do caminho. A afirmação é falsa."}, "n": 1}, {"id": "q092", "an": "volt_ev", "t": "po", "q": "O elétron-volt (eV) é uma unidade de:", "o": ["Energia.", "Carga.", "Potencial elétrico.", "Força."], "a": 0, "h": "Elétron multiplicado por volt.", "e": "1 eV é a energia ganha por um elétron ao atravessar 1 V: 1,6 × 10⁻¹⁹ J.", "x": {"1": "Carga é medida em coulombs.", "2": "O potencial é medido em volts.", "3": "Força é medida em newtons."}, "n": 1}, {"id": "q093", "an": "calc_q093", "t": "po", "q": "Qual é a energia potencial elétrica de duas cargas de +2 µC e +3 µC separadas por 0,6 m? (k = 9 × 10⁹ N·m²/C²)", "o": ["0,09 J", "0,9 J", "0,009 J", "0,054 J"], "a": 0, "h": "Use Ep = k·q₁·q₂ / d.", "e": "Ep = 9 × 10⁹ × 6 × 10⁻¹² / 0,6 = 0,09 J.", "c": 1, "x": {"1": "0,9 J tem fator 10 a mais.", "2": "0,009 J tem fator 10 a menos.", "3": "0,054 J não divide por d."}, "n": 2}, {"id": "q094", "t": "eq", "q": "O que é blindagem eletrostática?", "o": ["Proteção do interior de um condutor oco contra campos externos.", "Isolamento térmico de um condutor.", "Remoção das cargas de um isolante.", "Ligação de um corpo à terra."], "a": 0, "h": "Pense na gaiola de Faraday.", "e": "Em equilíbrio, o campo no interior de um condutor oco é nulo, mesmo com campos externos.", "x": {"1": "Não tem a ver com calor.", "2": "A blindagem não remove cargas.", "3": "Ligar à terra é aterramento."}, "an": "gaiola", "n": 1}, {"id": "q095", "an": "pot_cond", "t": "eq", "q": "Em um condutor carregado em equilíbrio, o campo elétrico logo fora da superfície é:", "o": ["Perpendicular à superfície.", "Paralelo à superfície.", "Nulo.", "Oblíquo, em qualquer ângulo."], "a": 0, "h": "Se houvesse componente paralela, as cargas escorregariam.", "e": "Se houvesse componente tangencial, as cargas se moveriam. Em equilíbrio, o campo é perpendicular à superfície.", "x": {"1": "O campo é perpendicular, porque se tivesse componente tangencial as cargas se moveriam.", "2": "Fora da superfície o campo não é nulo.", "3": "Qualquer ângulo oblíquo moveria cargas na superfície."}, "n": 2}, {"id": "q096", "an": "superf", "t": "eq", "q": "Verdadeiro ou falso: a carga em excesso de um condutor oco em equilíbrio fica na superfície interna.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "As cargas se afastam o máximo possível.", "e": "Em equilíbrio, a carga em excesso fica na superfície externa.", "v": 1, "x": {"0": "Em um condutor oco, as cargas em excesso ficam na superfície externa. A afirmação é falsa."}, "n": 1}, {"id": "q097", "t": "eq", "q": "Por que a carroceria metálica de um carro protege seus ocupantes de raios?", "o": ["O metal conduz a carga pela superfície externa.", "O metal é isolante e bloqueia a carga.", "O raio sempre é desviado pelo ar.", "O interior do carro é sempre aterrado."], "a": 0, "h": "Pense na gaiola de Faraday.", "e": "A carga se distribui pela superfície externa e escoa, e o campo no interior fica praticamente nulo.", "x": {"1": "O metal conduz, não isola.", "2": "O raio não é desviado pelo ar.", "3": "O carro não precisa estar aterrado."}, "an": "gaiola", "n": 2}, {"id": "q098", "an": "esferas_fio", "t": "eq", "q": "Dois condutores esféricos, um grande e um pequeno, são ligados por um fio metálico. No equilíbrio, eles têm:", "o": ["O mesmo potencial.", "A mesma carga.", "O mesmo campo na superfície.", "Carga nula."], "a": 0, "h": "O fio faz com que os dois formem um único condutor.", "e": "Ligados por fio, formam um só condutor: o potencial é o mesmo, mas as cargas se dividem de modo diferente.", "x": {"1": "Cargas diferentes, mas mesmo potencial.", "2": "O campo é diferente em superfícies de raios diferentes.", "3": "Eles ficam carregados."}, "n": 3}, {"id": "q099", "t": "eq", "q": "O para-raios tem ponta porque:", "o": ["O campo é mais intenso nas pontas, o que facilita a descarga.", "As pontas armazenam carga positiva.", "As pontas isolam o prédio.", "Pontas atraem somente cargas negativas."], "a": 0, "h": "Relacione com o poder das pontas.", "e": "O campo é mais intenso nas pontas, que facilitam o escoamento da carga até a terra.", "x": {"1": "As pontas não armazenam carga, apenas concentram campo.", "2": "As pontas não isolam o prédio.", "3": "Atraem cargas de qualquer sinal."}, "an": "pontas", "n": 1}, {"id": "q100", "an": "pot_cond", "t": "eq", "q": "Verdadeiro ou falso: o potencial no interior de um condutor oco carregado em equilíbrio é sempre nulo.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Campo nulo não significa potencial nulo.", "e": "O campo é nulo, mas o potencial é constante e igual ao da superfície, geralmente diferente de zero.", "v": 1, "x": {"0": "O potencial é constante, mas não precisa ser nulo. A afirmação é falsa."}, "n": 1}, {"id": "q101", "t": "eq", "q": "Por que os condutores de alta tensão em subestações têm superfícies arredondadas, sem pontas?", "o": ["Para evitar descargas, pois o campo é muito intenso nas pontas.", "Para armazenar mais carga nas pontas.", "Para reduzir a resistência térmica do material.", "Para que a carga fique concentrada em um ponto."], "a": 0, "h": "Relacione pontas com a intensidade do campo.", "e": "Em pontas o campo é muito intenso e pode ionizar o ar, causando descargas. Superfícies arredondadas evitam isso.", "x": {"1": "Pontas concentrariam o campo e causariam descargas.", "2": "A resistência térmica não é o motivo.", "3": "A concentração em pontos favorece descargas."}, "an": "pontas", "n": 2}, {"id": "q102", "an": "pontas", "t": "eq", "q": "Em um condutor carregado em equilíbrio, a densidade de cargas é maior:", "o": ["Nas regiões de menor raio de curvatura.", "Nas regiões de maior raio de curvatura.", "No interior do condutor.", "Em qualquer região plana."], "a": 0, "h": "Pontas têm raio de curvatura pequeno.", "e": "Quanto menor o raio de curvatura (ponta), maior a densidade de cargas e maior o campo.", "x": {"1": "O raio de curvatura é menor nas pontas, onde há mais carga.", "2": "No interior não há cargas.", "3": "Regiões planas têm menos carga."}, "n": 2}, {"id": "q103", "an": "pontas", "t": "eq", "q": "Verdadeiro ou falso: uma esfera lisa e uma agulha, ambas carregadas e em equilíbrio, têm a mesma concentração de cargas em toda a superfície.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Pense na forma de cada uma.", "e": "Na agulha a carga se concentra na ponta. Na esfera lisa, a distribuição é uniforme.", "v": 1, "x": {"0": "Na agulha a carga se concentra na ponta. A afirmação é falsa."}, "n": 1}, {"id": "q104", "t": "eq", "q": "O fenômeno chamado vento elétrico, junto a uma ponta carregada, acontece porque:", "o": ["O campo intenso ioniza o ar, e os íons são repelidos pela ponta.", "A ponta emite prótons para o ambiente.", "O ar esquenta e sobe, sem relação com cargas.", "A ponta atrai somente o oxigênio do ar."], "a": 0, "h": "Campo intenso pode arrancar elétrons das moléculas do ar.", "e": "O campo forte ioniza o ar. Íons de mesmo sinal da ponta são repelidos e produzem um fluxo de ar.", "x": {"1": "A ponta não emite prótons.", "2": "O efeito é elétrico, não térmico.", "3": "A ponta repele íons, e não atrai só oxigênio."}, "an": "vento", "n": 2}, {"id": "q105", "an": "esferas_fio", "t": "eq", "q": "Duas esferas condutoras, de raios R e 2R, são ligadas por um fio e entram em equilíbrio. Qual afirmação é correta?", "o": ["A esfera de raio R tem maior densidade de cargas.", "A esfera de raio 2R tem maior densidade de cargas.", "As duas têm a mesma densidade de cargas.", "A esfera de raio R fica neutra."], "a": 0, "h": "Mesmo potencial significa carga proporcional ao raio.", "e": "Com o mesmo potencial, Q ∝ R. A densidade σ = Q / (4πR²) ∝ 1/R, maior na esfera menor.", "x": {"1": "A esfera menor tem maior densidade, e não a maior.", "2": "As densidades são diferentes.", "3": "A esfera menor não fica neutra."}, "n": 3}, {"id": "q106", "an": "pararaios", "t": "eq", "q": "Por que é perigoso ficar em pé, em campo aberto, durante uma tempestade?", "o": ["O corpo é um ponto elevado, onde o campo é mais intenso e a descarga tende a chegar.", "O corpo humano é isolante e acumula carga.", "O ar fica carregado positivamente perto do solo.", "A tempestade neutraliza o campo elétrico do solo."], "a": 0, "h": "Pense em destaques no terreno.", "e": "Objetos altos e pontiagudos concentram o campo, o que favorece descargas. O ideal é se abrigar em locais fechados.", "x": {"1": "O corpo humano é condutor.", "2": "O ar não fica carregado perto do solo dessa forma.", "3": "A tempestade não neutraliza o campo."}, "n": 2}, {"id": "q107", "an": "choque", "t": "el", "q": "Em um dia seco, ao tirar um casaco de lã, você ouve estalos e vê faíscas no escuro. Qual é a origem desses fenômenos?", "o": ["Descargas entre superfícies eletrizadas por atrito.", "Reações químicas na lã.", "Aquecimento do tecido pela luz.", "Cargas criadas dentro do tecido."], "a": 0, "h": "Pense no atrito do casaco com a roupa de baixo.", "e": "O atrito eletriza as superfícies. Ao se separarem, a diferença de potencial provoca pequenas descargas no ar.", "x": {"1": "Não são reações químicas.", "2": "A luz não aquece o tecido assim.", "3": "Cargas não são criadas: são separadas pelo atrito."}, "n": 2}, {"id": "q108", "an": "corrente_caminhao", "t": "el", "q": "Caminhões de combustível costumam ter uma corrente metálica tocando o chão. Para que ela serve?", "o": ["Escoar para a terra a carga acumulada por atrito.", "Aumentar o atrito com o asfalto.", "Atrair raios para longe do caminhão.", "Gerar carga negativa no tanque."], "a": 0, "h": "Pense em ligar o caminhão à terra.", "e": "O atrito do combustível e do ar eletriza o veículo. A corrente liga ao solo e evita faíscas perigosas.", "x": {"1": "O objetivo não é aumentar o atrito.", "2": "A corrente não atrai raios.", "3": "Ela não gera carga."}, "n": 2}, {"id": "q109", "t": "eq", "q": "Pessoas dentro de um avião atingido por um raio normalmente não sofrem danos. Por quê?", "o": ["A fuselagem metálica conduz a carga por fora, e o campo interno é nulo.", "O avião é feito de material isolante.", "O raio é desviado pelas nuvens.", "A carga se acumula dentro da cabine."], "a": 0, "h": "Pense na gaiola de Faraday.", "e": "A carga escoa pela superfície externa metálica, e o campo no interior permanece praticamente nulo.", "x": {"1": "O avião é metálico, condutor.", "2": "O raio não é desviado pelas nuvens.", "3": "A carga fica na superfície externa."}, "an": "gaiola", "n": 2}, {"id": "q110", "t": "el", "q": "Um canudo plástico atritado é aproximado de um filete fino de água, que se curva em sua direção. Isso ocorre porque:", "o": ["As moléculas de água se polarizam, e surge atração.", "O canudo transfere prótons para a água.", "A água é isolante e fica positiva.", "A água é neutralizada pelo canudo."], "a": 0, "h": "A água é neutra, mas as moléculas têm lados positivo e negativo.", "e": "A água é neutra, mas polar. O canudo carregado orienta as moléculas e atrai o filete.", "x": {"1": "Prótons não se transferem.", "2": "A água é polar, não isolante.", "3": "O canudo não neutraliza a água."}, "an": "polariz", "n": 2}, {"id": "q111", "an": "calc_q111", "t": "po", "q": "Uma bateria de 1,5 V move 2 C de carga por um circuito. Qual é a energia fornecida?", "o": ["3 J", "0,75 J", "1,5 J", "1,33 J"], "a": 0, "h": "Use W = q·U.", "e": "W = q·U = 2 × 1,5 = 3 J.", "c": 1, "x": {"1": "0,75 J divide por 2.", "2": "1,5 J esquece a carga de 2 C.", "3": "1,33 J divide 2 por 1,5."}, "n": 2}, {"id": "q112", "an": "gota_oleo", "t": "ca", "q": "Uma gota de óleo com carga negativa fica em equilíbrio entre placas horizontais, sob campo elétrico vertical. A força elétrica sobre ela está:", "o": ["Para cima, equilibrando o peso.", "Para baixo, somando-se ao peso.", "Na horizontal, sem relação com o peso.", "Nula, pois a gota está parada."], "a": 0, "h": "Para ficar em equilíbrio, a força resultante é nula.", "e": "Em equilíbrio, a força elétrica tem o mesmo módulo do peso e sentido oposto: para cima.", "x": {"1": "Para baixo, a gota cairia.", "2": "A força elétrica tem direção vertical.", "3": "A gota parada tem força resultante nula, não força elétrica nula."}, "n": 3}, {"id": "q113", "an": "balao_fios", "t": "co", "q": "Dois balões carregados, pendurados lado a lado por fios, têm os fios afastados da vertical, um para cada lado. O que se conclui?", "o": ["Os balões se repelem eletricamente.", "Os balões se atraem.", "Os balões estão neutros.", "Os balões têm cargas de sinais opostos."], "a": 0, "h": "Os balões se afastam um do outro.", "e": "O afastamento indica repulsão, que só ocorre entre cargas de mesmo sinal.", "x": {"1": "Se se atraíssem, os fios se aproximariam.", "2": "Balões neutros não se afastariam.", "3": "Sinais opostos se atrairiam."}, "n": 2}, {"id": "q114", "an": "choque", "t": "el", "q": "Ao descer de um carro em dia seco, uma pessoa leva choque ao tocar a porta metálica. Que cuidado reduz esse efeito?", "o": ["Manter contato com a lataria ao sair, descarregando-se aos poucos.", "Sair do carro o mais rápido possível.", "Segurar um objeto isolante.", "Usar sempre sapatos de borracha."], "a": 0, "h": "Pense em manter um caminho para a carga escoar.", "e": "Manter contato com o metal enquanto sai evita acumular carga por atrito com o banco. Ao final, a pessoa não fica carregada.", "x": {"1": "Sair rapidamente não reduz o choque.", "2": "Um isolante não ajuda.", "3": "Sapatos de borracha mantêm a carga."}, "n": 2}, {"id": "q115", "t": "co", "q": "Verdadeiro ou falso: a força elétrica entre duas cargas é uma grandeza vetorial.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Pense se a força tem apenas valor ou também direção e sentido.", "e": "Toda força é vetorial: tem módulo, direção e sentido. Na lei de Coulomb, a direção é a da reta que liga as cargas.", "v": 1, "x": {"1": "A força elétrica tem módulo, direção e sentido. A afirmação é verdadeira."}, "n": 1}, {"id": "q116", "t": "co", "q": "Qual é a unidade da força elétrica no Sistema Internacional?", "o": ["Newton (N)", "Joule (J)", "Volt (V)", "Coulomb (C)"], "a": 0, "h": "Força elétrica é uma força, como qualquer outra.", "e": "Qualquer força é medida em newtons no SI. O joule mede energia, o volt mede potencial e o coulomb mede carga.", "x": {"1": "Joule é unidade de energia.", "2": "Volt é unidade de potencial.", "3": "Coulomb é unidade de carga."}, "n": 1}, {"id": "q117", "an": "par_forcas", "t": "co", "q": "Duas cargas elétricas exercem forças uma sobre a outra. Pela terceira lei de Newton, essas forças têm:", "o": ["O mesmo módulo e sentidos opostos.", "Módulos diferentes se as cargas forem diferentes.", "O mesmo módulo e o mesmo sentido.", "Módulos que dependem apenas da maior carga."], "a": 0, "h": "Lembre o par ação e reação.", "e": "As forças formam um par ação e reação: mesmo módulo, mesma direção e sentidos opostos, mesmo que as cargas sejam diferentes.", "x": {"1": "As forças têm sempre o mesmo módulo.", "2": "As forças têm sentidos opostos.", "3": "O módulo depende das duas cargas."}, "n": 2}, {"id": "q118", "an": "par_forcas", "t": "co", "q": "Em qual situação duas esferas carregadas se atraem?", "o": ["Quando têm cargas de sinais opostos.", "Quando têm cargas de mesmo sinal.", "Quando as duas estão neutras.", "Somente quando têm o mesmo valor de carga."], "a": 0, "h": "Cargas de mesmo sinal fazem o contrário.", "e": "Cargas de sinais opostos se atraem. Cargas de mesmo sinal se repelem.", "x": {"1": "Cargas de mesmo sinal se repelem.", "2": "Neutras não se atraem eletricamente.", "3": "O valor não importa, o sinal sim."}, "n": 1}, {"id": "q119", "an": "par_forcas", "t": "co", "q": "Duas cargas, q e 3q, de mesmo sinal, se repelem. Qual delas sofre a força de maior intensidade?", "o": ["Nenhuma: as duas sofrem forças de mesma intensidade.", "A carga 3q.", "A carga q.", "Depende de qual está mais perto do chão."], "a": 0, "h": "Pense no par ação e reação.", "e": "As forças trocadas entre as cargas têm sempre o mesmo módulo, F = k·q·3q / d², seja qual for o valor de cada carga.", "x": {"1": "A carga 3q sofre a mesma força.", "2": "A carga q sofre a mesma força.", "3": "A posição em relação ao chão não importa."}, "n": 2}, {"id": "q120", "t": "co", "q": "Se a distância entre duas cargas é triplicada, a força elétrica entre elas:", "o": ["Fica 9 vezes menor.", "Fica 3 vezes menor.", "Fica 3 vezes maior.", "Fica 9 vezes maior."], "a": 0, "h": "A força depende do inverso do quadrado da distância.", "e": "Como F é proporcional a 1/d², triplicar d divide F por 3² = 9.", "x": {"1": "F ∝ 1/d², então triplicar d divide por 9.", "2": "A força varia com 1/d², não 1/d.", "3": "A força diminui."}, "an": "coul_d3", "n": 2}, {"id": "q121", "an": "coul_grafico", "t": "co", "q": "Verdadeiro ou falso: a força elétrica entre duas cargas pontuais é diretamente proporcional ao produto dos módulos das cargas.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Observe o numerador da lei de Coulomb.", "e": "Em F = k·|q₁·q₂| / d², o produto das cargas está no numerador. Logo, F cresce na mesma proporção desse produto.", "v": 1, "x": {"1": "F = k·|q₁·q₂|/d²: é proporcional ao produto dos módulos. A afirmação é verdadeira."}, "n": 1}, {"id": "q122", "an": "coul_grafico", "t": "co", "q": "Por que o gráfico da força elétrica em função da distância é uma curva que cai rapidamente, e não uma reta?", "o": ["Porque a força é inversamente proporcional ao quadrado da distância.", "Porque a força é inversamente proporcional à distância.", "Porque a força não depende da distância.", "Porque a força aumenta com a distância."], "a": 0, "h": "Pense no expoente de d na lei de Coulomb.", "e": "Como F ∝ 1/d², a força diminui rapidamente quando a distância aumenta, o que dá uma curva e não uma reta.", "x": {"1": "Se fosse 1/d, a curva cairia mais devagar.", "2": "A força depende da distância.", "3": "A força diminui com a distância."}, "n": 2}, {"id": "q123", "t": "co", "q": "Verdadeiro ou falso: o valor da força elétrica entre duas cargas depende do meio em que elas estão.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "A constante k muda quando o meio muda.", "e": "A constante k depende do meio. No vácuo ela vale cerca de 9 × 10⁹ N·m²/C², e em outros meios o valor é menor.", "v": 1, "x": {"1": "A constante k muda conforme o meio, então a força muda. A afirmação é verdadeira."}, "n": 1}, {"id": "q124", "an": "grav_vs_ele", "t": "co", "q": "Entre um próton e um elétron, a força gravitacional é desprezível diante da elétrica. Isso acontece porque:", "o": ["As massas das partículas são minúsculas e a força elétrica envolve uma constante muito maior.", "A gravidade só existe entre planetas.", "As partículas não têm massa.", "A força elétrica não depende da distância."], "a": 0, "h": "Compare as massas das partículas com os valores de G e de k.", "e": "As massas atômicas são muito pequenas e a constante G é muito menor que k. Por isso, na escala das partículas, a força gravitacional pode ser desprezada.", "x": {"1": "A gravidade atua entre quaisquer massas.", "2": "As partículas têm massa muito pequena, não nula.", "3": "A força elétrica depende da distância."}, "n": 2}, {"id": "q125", "an": "par_forcas", "t": "co", "q": "Um pente carregado atrai pedaços de papel. Os pedaços de papel também puxam o pente. Isso ilustra:", "o": ["Que as forças formam um par ação e reação.", "Que o papel exerce uma força maior que o pente.", "Que o pente não exerce força.", "Que a força elétrica só age em um dos corpos."], "a": 0, "h": "Pense no que a terceira lei de Newton diz sobre qualquer interação.", "e": "Toda interação gera um par de forças de mesmo módulo e sentidos opostos, aplicadas em corpos diferentes.", "x": {"1": "Os dois puxam com forças de mesmo módulo.", "2": "O pente exerce força sobre o papel.", "3": "Ação e reação atuam em corpos diferentes."}, "n": 2}, {"id": "q126", "an": "calc_q126", "t": "co", "q": "Duas cargas de +4 µC e +4 µC estão a 0,2 m no vácuo. Qual é a força de repulsão entre elas? (k = 9 × 10⁹ N·m²/C²)", "o": ["3,6 N", "7,2 N", "0,36 N", "36 N"], "a": 0, "h": "Use F = k·q₁·q₂ / d², com as cargas em coulombs.", "e": "F = 9 × 10⁹ × 4 × 10⁻⁶ × 4 × 10⁻⁶ / (0,2)² = 0,144 / 0,04 = 3,6 N.", "c": 1, "x": {"1": "7,2 N dobra o valor correto.", "2": "0,36 N tem fator 10 a menos.", "3": "36 N tem fator 10 a mais."}, "n": 2}, {"id": "q127", "an": "carga_prova", "t": "ca", "q": "Verdadeiro ou falso: o campo elétrico existe em um ponto do espaço mesmo que não haja nenhuma carga de prova colocada nele.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "O campo é criado pela carga fonte.", "e": "O campo é produzido pela carga fonte e existe no espaço ao redor dela. A carga de prova só serve para detectá-lo.", "v": 1, "x": {"1": "O campo é uma propriedade do espaço criada pela fonte. A afirmação é verdadeira."}, "n": 1}, {"id": "q128", "t": "ca", "q": "Qual é a unidade do campo elétrico no Sistema Internacional?", "o": ["N/C", "N·C", "C/N", "J/C·m²"], "a": 0, "h": "Campo é força por unidade de carga.", "e": "Como E = F/q, a unidade é newton por coulomb (N/C), equivalente a V/m.", "x": {"1": "N·C é um produto, não uma razão.", "2": "C/N está invertida.", "3": "J/C·m² não é a unidade de E."}, "n": 1}, {"id": "q129", "an": "carga_prova", "t": "ca", "q": "Uma carga de prova positiva é colocada em um ponto onde o campo elétrico vale E. A força sobre ela:", "o": ["Tem o mesmo sentido de E.", "Tem sentido oposto ao de E.", "É perpendicular a E.", "É sempre nula."], "a": 0, "h": "Use F = q·E e observe o sinal de q.", "e": "Para carga positiva, F = q·E tem o mesmo sentido de E. Para carga negativa, o sentido é oposto.", "x": {"1": "O sentido oposto é para carga negativa.", "2": "A força é paralela ao campo.", "3": "A força não é nula, pois F = q·E."}, "n": 1}, {"id": "q130", "an": "linhas_cruz", "t": "ca", "q": "As linhas de campo elétrico de um sistema de cargas:", "o": ["Saem das cargas positivas e chegam às negativas.", "Saem das cargas negativas e chegam às positivas.", "Saem e chegam em qualquer carga.", "Nunca terminam em uma carga."], "a": 0, "h": "Lembre o sentido do campo perto de cada tipo de carga.", "e": "Por convenção, as linhas saem das cargas positivas e chegam às negativas.", "x": {"1": "Está invertido.", "2": "As linhas têm origem e fim conforme o sinal.", "3": "Elas terminam nas cargas negativas."}, "n": 2}, {"id": "q131", "an": "campo_dist", "t": "ca", "q": "Verdadeiro ou falso: quanto mais longe de uma carga puntiforme, mais intenso é o campo elétrico que ela produz.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Observe d no denominador de E = k·Q / d².", "e": "O campo é inversamente proporcional ao quadrado da distância: quanto mais longe, mais fraco.", "v": 1, "x": {"0": "Ao se afastar, E diminui com 1/d². A afirmação é falsa."}, "n": 1}, {"id": "q132", "t": "ca", "q": "Duas cargas, +Q e −Q, de mesmo módulo, são separadas por uma distância d. No ponto médio entre elas, o campo elétrico resultante aponta:", "o": ["Da carga positiva para a negativa.", "Da carga negativa para a positiva.", "Perpendicularmente à reta que liga as cargas.", "Em nenhuma direção, pois é nulo."], "a": 0, "h": "Desenhe os dois campos no ponto médio.", "e": "O campo da carga positiva se afasta dela e o da negativa se aproxima dela. No ponto médio, os dois apontam para o mesmo lado e se somam: da carga positiva para a negativa.", "f": "dipolo", "x": {"1": "Os dois campos apontam da carga positiva para a negativa no ponto médio.", "2": "O campo está na linha das cargas.", "3": "Os campos se somam, em vez de se anular."}, "an": "campo_pm", "n": 3}, {"id": "q133", "t": "ca", "q": "O vetor campo elétrico, em cada ponto de uma linha de campo, é:", "o": ["Tangente à linha.", "Perpendicular à linha.", "Paralelo à linha vizinha, mas nunca à própria linha.", "Sempre nulo."], "a": 0, "h": "A linha de campo mostra a direção do vetor.", "e": "Por construção, a linha de campo é tangente ao vetor campo em cada ponto, e o sentido da linha é o do vetor.", "x": {"1": "O campo é tangente à linha, e não perpendicular.", "2": "Está relacionado à própria linha.", "3": "O campo não é nulo."}, "n": 2}, {"id": "q134", "an": "carga_prova", "t": "ca", "q": "Qual é a diferença entre campo elétrico e força elétrica?", "o": ["O campo é uma propriedade do ponto, e a força depende da carga colocada nele.", "Não há diferença: são a mesma grandeza.", "O campo é escalar e a força é vetorial.", "O campo só existe quando há duas cargas."], "a": 0, "h": "Compare E = F/q com F = q·E.", "e": "O campo descreve o efeito da carga fonte em cada ponto. A força é o efeito sobre uma carga q colocada ali: F = q·E.", "x": {"1": "São grandezas diferentes: F = q·E.", "2": "Ambos são vetoriais.", "3": "Basta uma carga para criar campo."}, "n": 2}, {"id": "q135", "t": "ca", "q": "Em um campo elétrico uniforme, as linhas de campo são:", "o": ["Retas paralelas e igualmente espaçadas.", "Círculos concêntricos.", "Retas que se cruzam.", "Curvas que se afastam umas das outras."], "a": 0, "h": "Pense no campo entre duas placas paralelas.", "e": "Campo uniforme tem o mesmo módulo, direção e sentido em todos os pontos. Isso corresponde a linhas retas, paralelas e igualmente espaçadas.", "f": "placas", "x": {"1": "Círculos não formam um campo uniforme.", "2": "Linhas de campo não se cruzam.", "3": "Linhas que se afastam indicam campo não uniforme."}, "an": "placas", "n": 1}, {"id": "q136", "an": "carga_prova", "t": "ca", "q": "Verdadeiro ou falso: dobrar o valor da carga de prova colocada em um ponto dobra o campo elétrico nesse ponto.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "O campo é criado pela carga fonte, não pela carga de prova.", "e": "O campo não depende da carga de prova. O que dobra é a força sobre ela, pois F = q·E.", "v": 1, "x": {"0": "O campo é criado pela fonte e não depende da carga de prova. A afirmação é falsa."}, "n": 1}, {"id": "q137", "t": "ca", "q": "Uma carga negativa é abandonada em repouso em um campo elétrico uniforme. Ela começa a se mover:", "o": ["No sentido oposto ao do campo.", "No mesmo sentido do campo.", "Perpendicularmente ao campo.", "Ela não se move."], "a": 0, "h": "Para carga negativa, F e E têm sentidos opostos.", "e": "Sobre a carga negativa, a força tem sentido oposto ao do campo, e ela acelera nesse sentido.", "x": {"1": "O sentido do campo é o da carga positiva.", "2": "Há componente de força apenas na direção do campo.", "3": "A carga sofre força."}, "an": "unif_neg", "n": 2}, {"id": "q138", "an": "calc_q138", "t": "ca", "q": "Uma carga de 4 µC é colocada em um ponto onde o campo elétrico vale 500 N/C. Qual é a força sobre ela?", "o": ["2 × 10⁻³ N", "2 × 10³ N", "1,25 × 10⁸ N", "8 × 10⁻⁷ N"], "a": 0, "h": "Use F = q·E, com q em coulombs.", "e": "F = 4 × 10⁻⁶ × 500 = 2 × 10⁻³ N.", "c": 1, "x": {"1": "2 × 10³ N esquece a conversão de µC.", "2": "1,25 × 10⁸ N divide em vez de multiplicar.", "3": "8 × 10⁻⁷ N divide q por E."}, "n": 2}, {"id": "q139", "an": "pot_energia_igual", "t": "po", "q": "Uma carga positiva se afasta de uma carga positiva fixa. A energia potencial elétrica do sistema:", "o": ["Diminui.", "Aumenta.", "Fica constante.", "Fica sempre nula."], "a": 0, "h": "A força é de repulsão e realiza trabalho positivo.", "e": "A força repulsiva realiza trabalho positivo ao longo do afastamento, e a energia potencial diminui.", "x": {"1": "Cargas de mesmo sinal que se afastam liberam energia.", "2": "A distância muda, então a energia muda.", "3": "A energia só é nula no infinito."}, "n": 2}, {"id": "q140", "an": "volt_ev", "t": "po", "q": "Verdadeiro ou falso: a diferença de potencial entre dois pontos é medida em volts.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Lembre a unidade do potencial elétrico.", "e": "A diferença de potencial (ddp) é medida em volts (V), e 1 V equivale a 1 J/C.", "v": 1, "x": {"1": "O volt é a unidade de diferença de potencial. A afirmação é verdadeira."}, "n": 1}, {"id": "q141", "an": "volt_ev", "t": "po", "q": "O que significa dizer que a diferença de potencial entre dois pontos é de 1 volt?", "o": ["Que cada coulomb de carga recebe ou cede 1 joule de energia entre os pontos.", "Que a força entre os pontos é de 1 newton.", "Que a corrente entre os pontos é de 1 ampère.", "Que a carga entre os pontos é de 1 coulomb."], "a": 0, "h": "Use a relação 1 V = 1 J/C.", "e": "Um volt é um joule por coulomb: ao percorrer uma ddp de 1 V, cada coulomb de carga troca 1 J de energia.", "x": {"1": "Newton é unidade de força.", "2": "Ampère é unidade de corrente.", "3": "Coulomb é unidade de carga."}, "n": 2}, {"id": "q142", "t": "po", "q": "Cargas positivas abandonadas em repouso em um campo elétrico tendem a se mover para pontos de:", "o": ["Menor potencial.", "Maior potencial.", "Mesmo potencial.", "Potencial infinito."], "a": 0, "h": "A carga positiva acompanha o sentido do campo.", "e": "Cargas positivas seguem o sentido do campo, que aponta dos pontos de maior para os de menor potencial.", "x": {"1": "Cargas positivas vão para menores potenciais.", "2": "Elas se movem para potenciais diferentes.", "3": "O potencial infinito não é uma posição física."}, "an": "unif_pos", "n": 2}, {"id": "q143", "t": "po", "q": "Verdadeiro ou falso: cargas negativas abandonadas em repouso tendem a se mover para pontos de maior potencial.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "A força sobre carga negativa é oposta ao campo.", "e": "Como a carga negativa vai contra o campo, ela se desloca em direção aos pontos de maior potencial.", "v": 1, "x": {"1": "Cargas negativas vão para maior potencial. A afirmação é verdadeira."}, "an": "unif_neg", "n": 1}, {"id": "q144", "an": "equip", "t": "po", "q": "As superfícies equipotenciais são sempre:", "o": ["Perpendiculares às linhas de campo.", "Paralelas às linhas de campo.", "Iguais às linhas de campo.", "Tangentes às linhas de campo."], "a": 0, "h": "Pense no trabalho ao longo de uma equipotencial.", "e": "Se a força tivesse componente ao longo da superfície, o trabalho não seria nulo. Logo, o campo é perpendicular às equipotenciais.", "f": "equip", "x": {"1": "O campo cruza as equipotenciais em ângulo reto.", "2": "Equipotenciais e linhas de campo são diferentes.", "3": "Tangentes às linhas de campo seriam paralelas."}, "n": 1}, {"id": "q145", "t": "po", "q": "Qual é a diferença entre potencial elétrico e energia potencial elétrica?", "o": ["O potencial independe da carga colocada no ponto, e a energia depende dela.", "São sempre iguais.", "O potencial é vetorial e a energia é escalar.", "O potencial só existe em condutores."], "a": 0, "h": "Compare V = k·Q/d com Ep = q·V.", "e": "O potencial V é característico do ponto. A energia potencial de uma carga q nesse ponto é Ep = q·V.", "x": {"1": "São grandezas diferentes: U = q·V.", "2": "Ambos são escalares.", "3": "O potencial existe em qualquer ponto de um campo."}, "n": 2}, {"id": "q146", "an": "equip", "t": "po", "q": "Verdadeiro ou falso: entre dois pontos de mesmo potencial, o trabalho da força elétrica sobre uma carga é nulo.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Use W = q·(V_A − V_B).", "e": "Se V_A = V_B, a diferença de potencial é zero e o trabalho W = q·U também é zero.", "v": 1, "x": {"1": "Se V é igual, ΔV = 0, e o trabalho é zero. A afirmação é verdadeira."}, "n": 1}, {"id": "q147", "an": "pot_energia_oposta", "t": "po", "q": "A energia potencial elétrica de duas cargas de sinais opostos, quando elas se afastam:", "o": ["Aumenta.", "Diminui.", "Fica constante.", "Passa a ser negativa e diminui sempre."], "a": 0, "h": "A força é de atração e se opõe ao afastamento.", "e": "Para separar cargas que se atraem, é preciso realizar trabalho contra a força. Esse trabalho aumenta a energia potencial.", "x": {"1": "Para cargas opostas, afastar exige trabalho, e a energia aumenta.", "2": "A energia varia com a distância.", "3": "A energia aumenta, e não diminui."}, "n": 2}, {"id": "q148", "t": "po", "q": "Para um observador muito distante de uma carga puntiforme, o potencial elétrico produzido por ela tende a:", "o": ["Zero.", "Infinito.", "Um valor negativo qualquer.", "Um valor igual ao da carga."], "a": 0, "h": "Observe V = k·Q / d quando d é muito grande.", "e": "Quando d cresce, k·Q/d tende a zero. Por isso o potencial no infinito costuma ser tomado como referência.", "x": {"1": "O potencial tende a zero longe.", "2": "O potencial tende a zero, e não a um valor qualquer.", "3": "O potencial não é a carga."}, "n": 2}, {"id": "q149", "an": "calc_q149", "t": "po", "q": "Uma carga de 3 µC se desloca entre dois pontos com diferença de potencial de 50 V. Qual é o trabalho da força elétrica?", "o": ["1,5 × 10⁻⁴ J", "1,5 × 10⁻⁷ J", "1,7 × 10⁷ J", "150 J"], "a": 0, "h": "Use W = q·U, com q em coulombs.", "e": "W = 3 × 10⁻⁶ × 50 = 1,5 × 10⁻⁴ J.", "c": 1, "x": {"1": "1,5 × 10⁻⁷ J erra o expoente.", "2": "1,7 × 10⁷ J divide em vez de multiplicar.", "3": "150 J esquece a conversão de µC."}, "n": 2}, {"id": "q150", "t": "eq", "q": "Em um condutor em equilíbrio eletrostático, as cargas em excesso:", "o": ["Não têm movimento ordenado.", "Giram em círculos dentro do condutor.", "Fluem continuamente para a terra.", "Ficam sempre no centro."], "a": 0, "h": "Equilíbrio significa que não há corrente líquida.", "e": "No equilíbrio eletrostático, as cargas já se rearranjaram e não há movimento ordenado de cargas.", "x": {"1": "As cargas não giram.", "2": "Elas ficam na superfície, sem fluir continuamente.", "3": "Elas ficam na superfície."}, "an": "superf", "n": 1}, {"id": "q151", "an": "gaiola", "t": "eq", "q": "Verdadeiro ou falso: o campo elétrico no interior de um condutor maciço em equilíbrio eletrostático é nulo.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Se houvesse campo, as cargas livres se moveriam.", "e": "Com campo não nulo, as cargas livres se moveriam. Em equilíbrio, o campo interno é nulo.", "v": 1, "x": {"1": "O campo no interior do condutor em equilíbrio é nulo. A afirmação é verdadeira."}, "n": 1}, {"id": "q152", "an": "pot_cond", "t": "eq", "q": "A superfície de um condutor em equilíbrio eletrostático é:", "o": ["Uma superfície equipotencial.", "Uma região onde o campo elétrico é sempre nulo.", "Uma região onde o potencial muda de ponto a ponto.", "Uma região sem cargas."], "a": 0, "h": "Todo o condutor tem o mesmo potencial.", "e": "Todos os pontos do condutor em equilíbrio têm o mesmo potencial, e a superfície é equipotencial.", "x": {"1": "O campo fora da superfície não é nulo.", "2": "O potencial é o mesmo em toda a superfície.", "3": "Há cargas na superfície."}, "n": 2}, {"id": "q153", "an": "pot_cond", "t": "eq", "q": "Verdadeiro ou falso: em um condutor em equilíbrio, o potencial pode variar de um ponto a outro da superfície.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Pense na equipotencial.", "e": "Se o potencial variasse, haveria campo ao longo da superfície e as cargas se moveriam. Logo, o potencial é o mesmo em todos os pontos.", "v": 1, "x": {"0": "Todo o condutor é equipotencial. A afirmação é falsa."}, "n": 1}, {"id": "q154", "an": "gaiola", "t": "eq", "q": "Um condutor esférico oco está carregado e em equilíbrio. O campo elétrico dentro da cavidade vazia é:", "o": ["Nulo.", "Igual ao campo na superfície.", "Maior que fora.", "Dirigido para o centro."], "a": 0, "h": "Lembre a blindagem eletrostática.", "e": "Em equilíbrio, as cargas ficam na superfície externa e o campo dentro da cavidade vazia é nulo.", "x": {"1": "O campo é nulo dentro da cavidade, e é diferente do da superfície.", "2": "Dentro da cavidade o campo é nulo.", "3": "Não há campo dirigido ao centro."}, "n": 2}, {"id": "q155", "t": "eq", "q": "O chamado “poder das pontas” significa que, em um condutor carregado:", "o": ["As cargas se concentram nas regiões pontiagudas, onde o campo é mais intenso.", "As pontas ficam sempre neutras.", "As cargas se distribuem igualmente em qualquer formato.", "As pontas atraem apenas cargas negativas."], "a": 0, "h": "Pense na densidade de cargas.", "e": "Nas pontas, a densidade de cargas e o campo são maiores, o que pode ionizar o ar e provocar descargas.", "f": "pontas", "x": {"1": "As pontas concentram carga.", "2": "A distribuição não é igual em qualquer formato.", "3": "As pontas atraem qualquer sinal."}, "an": "pontas", "n": 2}, {"id": "q156", "t": "eq", "q": "Para proteger um equipamento sensível de campos elétricos externos, ele pode ser colocado:", "o": ["Dentro de uma caixa metálica fechada.", "Dentro de uma caixa de madeira.", "Sobre uma superfície de plástico.", "Preso a uma ponta metálica."], "a": 0, "h": "Pense na blindagem eletrostática.", "e": "Dentro de uma caixa metálica fechada, o campo elétrico externo é anulado, como em uma gaiola de Faraday.", "x": {"1": "A madeira não blinda campos.", "2": "Plástico não protege.", "3": "Pontas concentram campo."}, "an": "gaiola", "n": 2}, {"id": "q157", "t": "eq", "q": "Um condutor carregado e em equilíbrio é ligado à terra por um fio condutor. O que acontece com o excesso de carga?", "o": ["Ele escoa para a terra e o condutor se descarrega.", "Ele permanece todo no condutor.", "Ele dobra de valor.", "Ele se concentra na ponta do fio."], "a": 0, "h": "A terra funciona como um grande reservatório de cargas.", "e": "A terra é um enorme reservatório de carga. Ao ligá-la ao condutor, o excesso de carga escoa até que os potenciais se igualem.", "x": {"1": "Com a ligação à terra, a carga escoa.", "2": "A carga não dobra.", "3": "A carga não se concentra no fio."}, "n": 2}, {"id": "q158", "an": "superf", "t": "eq", "q": "Verdadeiro ou falso: em um condutor maciço em equilíbrio, as cargas em excesso podem ficar distribuídas no interior do volume.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Pense no que acontece com cargas de mesmo sinal.", "e": "As cargas de mesmo sinal se repelem e vão para a superfície. No interior do material maciço não fica carga em excesso.", "v": 1, "x": {"0": "As cargas em excesso ficam na superfície, não no volume. A afirmação é falsa."}, "n": 1}, {"id": "q159", "t": "eq", "q": "Em uma esfera condutora isolada, carregada e em equilíbrio, a carga em excesso se distribui na superfície de modo:", "o": ["Uniforme.", "Concentrado em um único ponto.", "Maior no interior que na superfície.", "Aleatório e variável no tempo."], "a": 0, "h": "A simetria da esfera ajuda.", "e": "Pela simetria da esfera, a repulsão mútua espalha a carga de forma uniforme sobre a superfície externa.", "x": {"1": "Em uma esfera, a simetria dá distribuição uniforme.", "2": "Não há carga no interior.", "3": "A distribuição é estável."}, "an": "superf", "n": 2}, {"id": "q160", "t": "co", "q": "Duas cargas puntiformes de +4 µC e +9 µC estão a 30 cm uma da outra, no vácuo. Qual é a intensidade da força elétrica entre elas? (k = 9 × 10⁹ N·m²/C²)", "o": ["3,6 N", "1,08 N", "36 N", "0,36 N"], "a": 0, "h": "Converta µC e cm para unidades do SI antes de usar F = k·q₁·q₂/d².", "e": "F = 9×10⁹ · (4×10⁻⁶)(9×10⁻⁶) / (0,3)² = 0,324 / 0,09 = 3,6 N.", "c": 1, "n": 3, "x": {"1": "1,08 N vem de dividir por d (0,3) em vez de d² (0,09).", "2": "36 N está dez vezes maior: confira as potências de dez.", "3": "0,36 N está dez vezes menor."}, "an": "calc_q160"}, {"id": "q161", "t": "co", "q": "Uma carga de +2 µC e outra de −5 µC estão a 0,2 m uma da outra. Qual é a força entre elas?", "o": ["2,25 N, de repulsão", "2,25 N, de atração", "0,45 N, de atração", "22,5 N, de atração"], "a": 1, "h": "O sinal só diz se atrai ou repele: use o módulo das cargas no cálculo.", "e": "|F| = 9×10⁹ · (2×10⁻⁶)(5×10⁻⁶) / (0,2)² = 0,09 / 0,04 = 2,25 N. Os sinais são opostos, então a força é de atração.", "c": 1, "n": 3, "x": {"0": "Cargas de sinais opostos se atraem, não se repelem.", "2": "0,45 N vem de dividir por d (0,2) em vez de d² (0,04).", "3": "22,5 N está dez vezes maior: confira as potências de dez."}, "an": "calc_q161"}, {"id": "q162", "t": "ca", "q": "Uma carga de prova de 2 µC é colocada a 0,5 m de uma carga fixa de +5 µC. Qual é a força sobre ela?", "o": ["1,8 × 10⁵ N", "0,18 N", "0,36 N", "0,72 N"], "a": 2, "h": "Primeiro ache o campo E = k·Q/d²; depois F = q·E.", "e": "E = 9×10⁹ · 5×10⁻⁶ / (0,5)² = 1,8×10⁵ N/C. F = q·E = 2×10⁻⁶ · 1,8×10⁵ = 0,36 N.", "c": 1, "n": 3, "x": {"0": "1,8×10⁵ é o campo (em N/C). Falta multiplicar pela carga de prova.", "1": "0,18 N seria para uma carga de prova de 1 µC: confira o valor de q.", "3": "0,72 N é o dobro do correto: a carga de prova foi contada duas vezes."}, "an": "calc_q162"}, {"id": "q163", "t": "po", "q": "Uma carga de 3 µC atravessa uma região onde a diferença de potencial é de 200 V e, em seguida, outra onde é de 150 V, sempre no mesmo sentido. Qual é o trabalho total da força elétrica?", "o": ["6 × 10⁻⁴ J", "4,5 × 10⁻⁴ J", "1,05 × 10⁻⁶ J", "1,05 × 10⁻³ J"], "a": 3, "h": "As diferenças de potencial se somam: W = q·(ΔV₁ + ΔV₂).", "e": "ΔV total = 200 + 150 = 350 V. W = q·ΔV = 3×10⁻⁶ · 350 = 1,05×10⁻³ J.", "c": 1, "n": 3, "x": {"0": "6×10⁻⁴ J usa só os 200 V e esquece a segunda região.", "1": "4,5×10⁻⁴ J usa só os 150 V e esquece a primeira região.", "2": "1,05×10⁻⁶ J erra a potência de dez na conversão de µC."}, "an": "calc_q163"}, {"id": "q164", "t": "po", "q": "Em um campo elétrico uniforme de 400 N/C, uma carga de 2 µC é deslocada 0,25 m no sentido do campo. Qual é o trabalho da força elétrica?", "o": ["2 × 10⁻⁴ J", "8 × 10⁻⁴ J", "2 × 10⁻⁶ J", "3,2 × 10⁻³ J"], "a": 0, "h": "W = F·d, e a força é F = q·E.", "e": "F = q·E = 2×10⁻⁶ · 400 = 8×10⁻⁴ N. W = F·d = 8×10⁻⁴ · 0,25 = 2×10⁻⁴ J.", "c": 1, "n": 3, "x": {"1": "8×10⁻⁴ é a força qE, em newtons. Falta multiplicar pelo deslocamento.", "2": "2×10⁻⁶ é o valor da carga, não o trabalho.", "3": "3,2×10⁻³ vem de dividir a força pelo deslocamento em vez de multiplicar."}, "an": "calc_q164"}, {"id": "q165", "t": "po", "q": "Um elétron parte do repouso e é acelerado por uma diferença de potencial de 500 V. Qual é, aproximadamente, a velocidade final? (e = 1,6 × 10⁻¹⁹ C; m = 9,1 × 10⁻³¹ kg)", "o": ["1,8 × 10¹⁴ m/s", "1,3 × 10⁷ m/s", "9,4 × 10⁶ m/s", "2,7 × 10⁷ m/s"], "a": 1, "h": "A energia ganha é e·ΔV e vira energia cinética: e·ΔV = mv²/2.", "e": "Ec = e·ΔV = 1,6×10⁻¹⁹ · 500 = 8×10⁻¹⁷ J. v = √(2·Ec/m) = √(1,6×10⁻¹⁶ / 9,1×10⁻³¹) ≈ 1,3×10⁷ m/s.", "c": 1, "n": 3, "x": {"0": "1,8×10¹⁴ é o valor de v²: esqueceu a raiz quadrada.", "2": "9,4×10⁶ vem de esquecer o fator 2 na energia cinética (mv²/2).", "3": "2,7×10⁷ corresponderia a uma ddp de 2 000 V, não de 500 V."}, "an": "calc_q165"}, {"id": "q166", "t": "ca", "q": "Uma gotícula de óleo de massa 1,6 × 10⁻¹⁴ kg fica em equilíbrio entre duas placas horizontais, onde o campo elétrico é de 5 × 10⁵ N/C. Qual é o módulo da carga da gota? (g = 10 m/s²)", "o": ["1,6 × 10⁻¹⁹ C", "3,2 × 10⁻²⁰ C", "3,2 × 10⁻¹⁹ C", "3,2 × 10⁻⁹ C"], "a": 2, "h": "No equilíbrio, a força elétrica compensa o peso: q·E = m·g.", "e": "m·g = 1,6×10⁻¹⁴ · 10 = 1,6×10⁻¹³ N. q = m·g/E = 1,6×10⁻¹³ / 5×10⁵ = 3,2×10⁻¹⁹ C (o dobro da carga de um elétron).", "c": 1, "n": 3, "x": {"0": "1,6×10⁻¹⁹ C é a carga de um só elétron; aqui m·g/E dá o dobro.", "1": "3,2×10⁻²⁰ C está dez vezes menor: confira as potências de dez.", "3": "3,2×10⁻⁹ C está dez bilhões de vezes maior: erro nas potências de dez."}, "an": "calc_q166"}, {"id": "q167", "t": "co", "q": "Duas esferas condutoras idênticas têm cargas +8 µC e −2 µC. Elas são colocadas em contato e depois afastadas até 0,3 m. Qual é a força entre elas?", "o": ["0,9 N, de atração", "1,6 N, de atração", "2,5 N, de repulsão", "0,9 N, de repulsão"], "a": 3, "h": "No contato entre condutores idênticos, a carga total se divide igualmente.", "e": "Carga final de cada esfera: (8 − 2)/2 = +3 µC. F = 9×10⁹ · (3×10⁻⁶)² / (0,3)² = 0,081 / 0,09 = 0,9 N, de repulsão.", "c": 1, "n": 3, "x": {"0": "Depois do contato as duas ficam com cargas de mesmo sinal, que se repelem.", "1": "1,6 N usa as cargas antes do contato; elas mudam ao se tocar.", "2": "2,5 N vem de (8 + 2)/2 = 5 µC, ignorando o sinal negativo de −2 µC."}, "an": "calc_q167"}, {"id": "q168", "t": "ca", "q": "Duas cargas positivas, q₁ = 2 µC e q₂ = 8 µC, estão separadas por 0,6 m. A que distância de q₁, sobre a reta que as une, o campo elétrico resultante é nulo?", "o": ["0,2 m", "0,3 m", "0,4 m", "0,12 m"], "a": 0, "h": "Entre cargas de mesmo sinal os campos se opõem: iguale k·q₁/x² e k·q₂/(0,6 − x)².", "e": "q₁/x² = q₂/(0,6 − x)² → (0,6 − x)/x = √(8/2) = 2 → 0,6 − x = 2x → x = 0,2 m.", "c": 1, "n": 3, "x": {"1": "O ponto médio só serve se as cargas forem iguais; aqui q₂ é quatro vezes maior.", "2": "0,4 m está mais perto da carga maior, mas o campo nulo fica mais perto da menor.", "3": "0,12 m vem de usar a razão 4 em vez de sua raiz quadrada (2)."}, "an": "calc_q168"}, {"id": "q169", "t": "po", "q": "Duas cargas de +3 µC e +6 µC estão a 0,9 m uma da outra. Qual é a energia potencial elétrica do par? (k = 9 × 10⁹ N·m²/C²)", "o": ["0,162 J", "0,18 J", "0,20 J", "1,8 J"], "a": 1, "h": "A energia potencial do par usa a distância sem elevar ao quadrado.", "e": "U = k·q₁·q₂/d = 9×10⁹ · (3×10⁻⁶)(6×10⁻⁶) / 0,9 = 0,162 / 0,9 = 0,18 J.", "c": 1, "n": 3, "x": {"0": "0,162 J esquece de dividir pela distância.", "2": "0,20 J usa d² em vez de d: a energia potencial é U = k·q₁·q₂/d.", "3": "1,8 J está dez vezes maior: confira as potências de dez."}, "an": "calc_q169"}, {"id": "q170", "t": "po", "q": "Uma carga puntiforme de +4 µC cria potencial V = k·Q/d. Qual é a diferença de potencial entre um ponto a 0,6 m e outro a 1,2 m dessa carga?", "o": ["6,0 × 10⁴ V", "3,6 × 10⁴ V", "3,0 × 10⁴ V", "1,5 × 10⁴ V"], "a": 2, "h": "Calcule V em cada ponto e subtraia.", "e": "V₁ = 9×10⁹ · 4×10⁻⁶ / 0,6 = 6×10⁴ V; V₂ = 9×10⁹ · 4×10⁻⁶ / 1,2 = 3×10⁴ V. ΔV = V₁ − V₂ = 3×10⁴ V.", "c": 1, "n": 3, "x": {"0": "6,0×10⁴ V é o potencial no ponto mais próximo, não a diferença.", "1": "3,6×10⁴ V é k·Q sem dividir pela distância.", "3": "1,5×10⁴ V é metade do valor correto: o potencial a 1,2 m foi subtraído duas vezes."}, "an": "calc_q170"}, {"id": "q171", "t": "ca", "q": "Uma esfera de massa 0,02 kg e carga 4 µC, presa a um fio, fica em equilíbrio a 45° da vertical em um campo elétrico horizontal uniforme. Qual é o módulo do campo? (g = 10 m/s²)", "o": ["2 × 10⁻⁵ N/C", "1 × 10⁵ N/C", "5 × 10³ N/C", "5 × 10⁴ N/C"], "a": 3, "h": "A 45°, tan 45° = 1, então a força elétrica é igual ao peso.", "e": "tan 45° = q·E/(m·g) = 1 → E = m·g/q = 0,02·10 / 4×10⁻⁶ = 5×10⁴ N/C.", "c": 1, "n": 3, "x": {"0": "2×10⁻⁵ vem de inverter a razão: q/(m·g) em vez de m·g/q.", "1": "1×10⁵ é o dobro do correto: a força elétrica é igual ao peso a 45°, sem fator 2.", "2": "5×10³ está dez vezes menor: confira as potências de dez."}, "an": "calc_q171"}, {"id": "q172", "t": "ce", "q": "Quem é o cientista desenhado na figura, que, segundo a tradição, notou que o âmbar atritado atrai pedacinhos de palha?", "o": ["Tales de Mileto", "Benjamin Franklin", "Charles Coulomb", "Michael Faraday"], "a": 0, "h": "Ele viveu na Grécia Antiga, por volta de 600 a.C.", "e": "Segundo relatos antigos, Tales de Mileto (cerca de 624–546 a.C.) teria notado que o âmbar, depois de atritado, atrai corpos leves. A palavra eletricidade vem de elektron, nome grego do âmbar (o termo elétrico foi criado por William Gilbert, em 1600).", "f": "ret_tales", "x": {"1": "Franklin viveu no século XVIII, muito depois da observação do âmbar.", "2": "Coulomb mediu forças entre cargas, mas não foi quem notou o efeito do âmbar.", "3": "Faraday estudou campos e indução no século XIX."}, "n": 1}, {"id": "q173", "t": "ce", "q": "Quem é o cientista desenhado na figura, que inventou o para-raios e propôs chamar as cargas de positivas e negativas?", "o": ["Charles Coulomb", "Benjamin Franklin", "Michael Faraday", "Alessandro Volta"], "a": 1, "h": "Ele também foi um dos fundadores dos Estados Unidos.", "e": "Benjamin Franklin (1706–1790) mostrou que os raios são fenômenos elétricos, inventou o para-raios e propôs os sinais positivo e negativo para as cargas.", "f": "ret_franklin", "x": {"0": "Coulomb estudou a força entre cargas, não o para-raios.", "2": "Faraday não inventou o para-raios.", "3": "Volta inventou a pilha elétrica."}, "n": 1}, {"id": "q174", "t": "ce", "q": "Quem é o cientista desenhado na figura, que mediu a força entre cargas elétricas usando uma balança de torção?", "o": ["Michael Faraday", "Alessandro Volta", "Charles Coulomb", "Tales de Mileto"], "a": 2, "h": "A unidade de carga elétrica do SI leva o nome dele.", "e": "Charles Augustin de Coulomb (1736–1806) usou a balança de torção e mostrou que a força entre duas cargas é proporcional ao produto das cargas e inversamente proporcional ao quadrado da distância.", "f": "ret_coulomb", "x": {"0": "Faraday é lembrado pelo campo e pela indução.", "1": "Volta é lembrado pela pilha e pela unidade de tensão.", "3": "Tales não mediu forças entre cargas."}, "n": 1}, {"id": "q175", "t": "ce", "q": "Quem é o cientista desenhado na figura, que criou a ideia de linhas de força para representar o campo elétrico?", "o": ["Alessandro Volta", "Tales de Mileto", "Benjamin Franklin", "Michael Faraday"], "a": 3, "h": "Uma gaiola metálica que blinda o campo elétrico leva o nome dele.", "e": "Michael Faraday (1791–1867) introduziu as linhas de força, estudou a indução eletromagnética e mostrou que, dentro de um condutor oco, o campo elétrico é nulo (gaiola de Faraday).", "f": "ret_faraday", "x": {"0": "Volta construiu a pilha.", "1": "Tales viveu muito antes dos estudos sobre campo.", "2": "Franklin não introduziu as linhas de força."}, "n": 1}, {"id": "q176", "t": "ce", "q": "Quem é o cientista desenhado na figura, que construiu a primeira pilha elétrica?", "o": ["Alessandro Volta", "Tales de Mileto", "Benjamin Franklin", "Charles Coulomb"], "a": 0, "h": "A unidade de potencial elétrico leva o nome dele.", "e": "Alessandro Volta (1745–1827) construiu a pilha, formada por discos de metais diferentes separados por tecido úmido. O volt, unidade de potencial elétrico, homenageia o cientista.", "f": "ret_volta", "x": {"1": "Tales viveu na Antiguidade e não construiu pilhas.", "2": "Franklin é lembrado pelo para-raios.", "3": "Coulomb é lembrado pela balança de torção."}, "n": 1}, {"id": "q177", "t": "ce", "q": "Verdadeiro ou falso: a palavra eletricidade vem de elektron, o nome grego do âmbar.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Pense na observação de Tales de Mileto.", "e": "Os gregos chamavam o âmbar de elektron. Como ele atrai corpos leves quando atritado, o fenômeno ficou conhecido como eletricidade.", "v": 1, "x": {"1": "A afirmação é verdadeira: eletricidade vem de elektron, o âmbar."}, "n": 1}, {"id": "q178", "t": "ce", "q": "Verdadeiro ou falso: segundo Franklin, o vidro atritado com seda fica com carga negativa.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "Ele chamou a carga do vidro de positiva.", "e": "Franklin chamou de positiva a carga adquirida pelo vidro atritado com seda. Hoje se sabe que o vidro perde elétrons.", "v": 1, "x": {"0": "Franklin chamou de positiva a carga do vidro. A afirmação é falsa."}, "n": 1}, {"id": "q179", "an": "gaiola", "t": "ce", "q": "Verdadeiro ou falso: dentro de uma gaiola de Faraday, o campo elétrico externo não penetra.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Pense em um condutor oco em equilíbrio.", "e": "Em um condutor oco em equilíbrio, as cargas se distribuem na superfície e o campo elétrico no interior é nulo. Por isso o carro funciona como uma gaiola durante uma tempestade.", "v": 1, "x": {"1": "A afirmação é verdadeira: o campo no interior é nulo."}, "n": 1},{"id": "q180", "t": "ca", "q": "Em uma região do espaço, as linhas de campo estão bem mais juntas perto do ponto A do que perto do ponto B. O que isso indica?", "o": ["O campo elétrico é mais intenso em A do que em B.", "O campo elétrico é mais intenso em B do que em A.", "O campo elétrico tem o mesmo módulo em A e em B.", "Há carga negativa em A e positiva em B."], "a": 0, "h": "Pense no que a concentração de linhas representa.", "e": "A densidade das linhas representa a intensidade do campo: onde elas estão mais próximas, o campo é mais intenso.", "x": {"1": "Inverteu a relação: mais linhas juntas significa campo mais forte.", "2": "Se o campo fosse igual, as linhas teriam o mesmo espaçamento.", "3": "O sinal das cargas não é dado pelo espaçamento das linhas."}, "n": 1},{"id": "q181", "t": "ca", "q": "As linhas de campo de um dipolo elétrico (uma carga +Q e uma carga −Q) são desenhadas:", "o": ["Saindo da carga positiva e chegando à carga negativa.", "Saindo da carga negativa e chegando à positiva.", "Saindo das duas cargas, sem se encontrar.", "Chegando às duas cargas, vindas do infinito."], "a": 0, "h": "Lembre a convenção de sentido: o campo aponta como a força sobre uma carga de prova positiva.", "e": "Por convenção, as linhas de campo saem das cargas positivas e chegam às negativas.", "x": {"1": "Isso inverte o sentido convencional das linhas.", "2": "Isso só vale para duas cargas positivas.", "3": "Isso só vale para duas cargas negativas."}, "n": 1},{"id": "q182", "t": "ca", "q": "Em qualquer ponto de uma linha de campo elétrico, o vetor campo elétrico é:", "o": ["Tangente à linha, no sentido dela.", "Perpendicular à linha.", "Sempre vertical, para cima.", "Nulo, pois a linha é só um desenho."], "a": 0, "h": "Pense na direção em que uma carga de prova positiva seria empurrada.", "e": "O vetor campo elétrico tangencia a linha de campo em cada ponto e tem o mesmo sentido dela.", "x": {"1": "O campo é perpendicular às superfícies equipotenciais, não às linhas.", "2": "A direção depende do campo, não é sempre vertical.", "3": "O desenho representa um campo real, que pode ser intenso."}, "n": 2},{"id": "q183", "t": "ca", "q": "Duas cargas positivas e iguais ficam próximas uma da outra. O que se observa nas linhas de campo na região entre elas?", "o": ["As linhas se afastam uma das outras, sem se cruzar, e há um ponto no meio onde o campo é nulo.", "As linhas ligam as duas cargas, como em um dipolo.", "As linhas ficam paralelas e igualmente espaçadas.", "As linhas se cruzam no ponto médio."], "a": 0, "h": "O campo é a soma vetorial dos campos das duas cargas.", "e": "Cargas de mesmo sinal repelem as linhas: elas se curvam e se afastam. No ponto médio os campos das duas cargas se anulam.", "x": {"1": "Linhas que ligam as cargas aparecem quando elas têm sinais opostos.", "2": "Linhas paralelas e uniformes aparecem entre placas, não entre duas cargas puntiformes.", "3": "Linhas de campo nunca se cruzam."}, "n": 3},{"id": "q184", "an": "calc_q184", "t": "ca", "q": "Uma carga de prova de 3 µC, colocada em um ponto, sofre uma força de 0,12 N. Qual é a intensidade do campo elétrico nesse ponto?", "o": ["4,0 × 10⁴ N/C", "3,6 × 10⁻⁷ N/C", "4,0 × 10⁻⁵ N/C", "0,36 N/C"], "a": 0, "h": "Use E = F / q com a carga em coulomb.", "e": "E = F / q = 0,12 / (3 × 10⁻⁶) = 4,0 × 10⁴ N/C.", "c": 1, "x": {"1": "Multiplicou F por q em vez de dividir.", "2": "Inverteu a divisão (q / F) e errou o expoente.", "3": "Usou q = 3 C no lugar de 3 µC."}, "n": 2},{"id": "q185", "an": "calc_q185", "t": "ca", "q": "Um elétron (carga de módulo 1,6 × 10⁻¹⁹ C) está em um campo elétrico uniforme de 2 000 N/C. Qual é a intensidade da força elétrica sobre ele?", "o": ["3,2 × 10⁻¹⁶ N", "8,0 × 10⁻²³ N", "3,2 × 10⁻¹⁹ N", "1,3 × 10²² N"], "a": 0, "h": "A força é o produto da carga pelo campo.", "e": "F = |q| · E = 1,6 × 10⁻¹⁹ × 2 000 = 3,2 × 10⁻¹⁶ N.", "c": 1, "x": {"1": "Dividiu a carga pelo campo.", "2": "Esqueceu de multiplicar pelo campo (usou só 2 × 1,6 × 10⁻¹⁹).", "3": "Dividiu o campo pela carga."}, "n": 2},{"id": "q186", "t": "ca", "q": "Em um ponto de campo elétrico, a carga de prova é trocada por outra com o dobro do valor (mesmo sinal). O que acontece?", "o": ["O campo no ponto continua o mesmo e a força sobre a carga dobra.", "O campo dobra e a força também dobra.", "O campo dobra e a força continua a mesma.", "O campo e a força continuam os mesmos."], "a": 0, "h": "Quem cria o campo? E de que depende a força?", "e": "O campo depende da carga que o cria, não da carga de prova. Como F = q·E, dobrando q a força dobra.", "x": {"1": "O campo E = F/q não depende da carga de prova.", "2": "O campo não muda com a carga de prova, e a força muda.", "3": "Se q dobra e E é o mesmo, a força dobra."}, "n": 2},{"id": "q187", "t": "ca", "q": "Um próton e um elétron são colocados, um de cada vez, no mesmo ponto de um campo elétrico uniforme. As forças sobre eles têm:", "o": ["Mesma intensidade e sentidos opostos.", "Intensidades diferentes e mesmo sentido.", "Mesma intensidade e mesmo sentido.", "Intensidades diferentes e sentidos opostos."], "a": 0, "h": "Compare o módulo e o sinal das duas cargas.", "e": "As cargas têm o mesmo módulo, então F = |q|·E é igual nos dois. Como os sinais são opostos, os sentidos são opostos.", "x": {"1": "Os módulos das cargas são iguais, logo as forças têm mesma intensidade.", "2": "Sinais opostos fazem os sentidos serem opostos.", "3": "As intensidades são iguais e os sentidos são opostos."}, "n": 2},{"id": "q188", "an": "calc_q188", "t": "po", "q": "Duas cargas, +5 µC e −2 µC, estão separadas por 0,3 m, no vácuo. Qual é a energia potencial elétrica do sistema? (k = 9 × 10⁹ N·m²/C²)", "o": ["−0,30 J", "+0,30 J", "−0,090 J", "−3,0 J"], "a": 0, "h": "Mantenha o sinal das cargas na fórmula.", "e": "U = k·q₁·q₂ / d = 9 × 10⁹ × 5 × 10⁻⁶ × (−2 × 10⁻⁶) / 0,3 = −0,30 J. O sinal é negativo porque as cargas têm sinais opostos.", "c": 1, "x": {"1": "Ignorou o sinal negativo da segunda carga.", "2": "Dividiu por d² em vez de d.", "3": "Errou uma potência de dez."}, "n": 3},{"id": "q189", "an": "calc_q189", "t": "po", "q": "Uma carga de 2 µC está em um campo elétrico uniforme de 500 N/C e é deslocada 0,4 m no sentido contrário ao da força elétrica. Quanta energia potencial elétrica ela ganha?", "o": ["4,0 × 10⁻⁴ J", "1,0 × 10⁻³ J", "2,5 × 10⁻³ J", "4,0 × 10⁻¹ J"], "a": 0, "h": "Use q·E·d, com a carga em coulomb.", "e": "A energia ganha é igual ao trabalho do agente externo: q·E·d = 2 × 10⁻⁶ × 500 × 0,4 = 4,0 × 10⁻⁴ J.", "c": 1, "x": {"1": "Errou o expoente ao converter µC.", "2": "Calculou q·E sem multiplicar por 0,4 m de forma correta e errou a escala.", "3": "Usou 2 C no lugar de 2 µC."}, "n": 3},{"id": "q190", "t": "po", "q": "Uma partícula de carga negativa é atraída para perto de um núcleo positivo fixo. Como varia a energia potencial elétrica do conjunto durante a aproximação?", "o": ["Diminui, pois as cargas se atraem e a força realiza trabalho positivo.", "Aumenta, pois as cargas ficam mais próximas.", "Não muda, pois só a velocidade muda.", "Passa a ser sempre positiva."], "a": 0, "h": "Quem realiza trabalho: a força elétrica ou um agente externo?", "e": "Cargas de sinais opostos se atraem. Ao se aproximarem, a força elétrica realiza trabalho positivo e a energia potencial diminui.", "x": {"1": "Aproximar cargas de sinais opostos libera energia, não armazena.", "2": "A distância muda, então a energia potencial muda.", "3": "Para sinais opostos a energia potencial é negativa."}, "n": 2},{"id": "q191", "t": "po", "q": "Duas cargas de mesmo sinal, mantidas próximas, são soltas e começam a se repelir. O que acontece com as energias do sistema, enquanto se afastam?", "o": ["A energia cinética aumenta e a energia potencial elétrica diminui.", "A energia cinética diminui e a potencial aumenta.", "As duas energias aumentam.", "As duas energias diminuem."], "a": 0, "h": "Pense na conservação da energia mecânica.", "e": "A repulsão realiza trabalho positivo: a energia potencial vira energia cinética, e a soma permanece constante.", "x": {"1": "Isso aconteceria se um agente externo forçasse as cargas a se aproximar.", "2": "A soma das duas se conserva, então não podem aumentar juntas.", "3": "A soma das duas se conserva, então não podem diminuir juntas."}, "n": 2},{"id": "q192", "an": "calc_q192", "t": "po", "q": "Uma carga de 8 µC se desloca de um ponto a 300 V até outro a 120 V. Qual é o trabalho da força elétrica sobre ela?", "o": ["1,44 × 10⁻³ J", "3,36 × 10⁻³ J", "2,4 × 10⁻³ J", "1,44 × 10³ J"], "a": 0, "h": "O trabalho é a carga vezes a diferença de potencial entre os pontos.", "e": "W = q·(V_inicial − V_final) = 8 × 10⁻⁶ × (300 − 120) = 1,44 × 10⁻³ J.", "c": 1, "x": {"1": "Somou os potenciais (300 + 120).", "2": "Usou só o potencial inicial (300 V).", "3": "Esqueceu de converter µC para C."}, "n": 2},{"id": "q193", "an": "calc_q193", "t": "po", "q": "Duas placas paralelas, separadas por 2 cm, têm entre elas uma diferença de potencial de 600 V. Qual é a intensidade do campo elétrico uniforme entre as placas?", "o": ["3,0 × 10⁴ V/m", "1,2 × 10⁴ V/m", "3,0 × 10² V/m", "1,2 × 10³ V/m"], "a": 0, "h": "Converta a distância para metros e use E = U / d.", "e": "d = 2 cm = 0,02 m. E = U / d = 600 / 0,02 = 3,0 × 10⁴ V/m.", "c": 1, "x": {"1": "Multiplicou U por d em vez de dividir.", "2": "Usou d = 2 m em vez de 0,02 m e errou.", "3": "Usou d = 2 m e dividiu."}, "n": 2},{"id": "q194", "t": "po", "q": "A diferença de potencial entre dois pontos de uma mesma superfície equipotencial vale:", "o": ["Zero.", "Metade do potencial da superfície.", "O potencial da superfície.", "Infinita."], "a": 0, "h": "Equipotencial: o mesmo potencial em todos os pontos.", "e": "Pontos de uma equipotencial têm o mesmo potencial, então a diferença entre eles é zero.", "x": {"1": "Não existe 'metade' aqui: os potenciais são iguais.", "2": "A ddp é a diferença, não o valor do potencial.", "3": "Não há razão para a ddp ser infinita."}, "n": 1},{"id": "q195", "t": "po", "q": "Verdadeiro ou falso: um passarinho pousado em um fio de alta tensão não leva choque porque seus dois pés estão praticamente no mesmo potencial.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "O que provoca a passagem de corrente pelo corpo?", "e": "A corrente depende da diferença de potencial entre os pontos de contato. Com os pés no mesmo fio, a ddp é praticamente nula.", "x": {"1": "A afirmação é verdadeira: sem ddp entre os pés, não há corrente relevante pelo corpo."}, "n": 2, "v": 1},{"id": "q196", "an": "calc_q196", "t": "di", "q": "Uma chapa metálica de 0,02 m² de área recebe uma carga de 6 µC distribuída uniformemente. Qual é a densidade superficial de cargas?", "o": ["3,0 × 10⁻⁴ C/m²", "1,2 × 10⁻⁷ C/m²", "3,0 × 10⁻³ C/m²", "1,2 × 10⁻⁴ C/m²"], "a": 0, "h": "A densidade superficial é a carga por unidade de área.", "e": "σ = Q / A = 6 × 10⁻⁶ / 0,02 = 3,0 × 10⁻⁴ C/m².", "c": 1, "x": {"1": "Multiplicou Q por A.", "2": "Errou o expoente ao dividir.", "3": "Usou A = 0,05 m²."}, "n": 2},{"id": "q197", "an": "calc_q197", "t": "di", "q": "Uma esfera condutora de raio 0,1 m tem carga de 4 µC. Considerando a carga uniformemente distribuída na superfície, qual é a densidade superficial de cargas? (área da esfera = 4πR²)", "o": ["3,2 × 10⁻⁵ C/m²", "4,0 × 10⁻⁵ C/m²", "1,3 × 10⁻⁴ C/m²", "3,2 × 10⁻³ C/m²"], "a": 0, "h": "Calcule primeiro a área da superfície esférica.", "e": "A = 4πR² = 4π × 0,01 ≈ 0,126 m². σ = Q / A = 4 × 10⁻⁶ / 0,126 ≈ 3,2 × 10⁻⁵ C/m² (resultado ≈ 3,18 × 10⁻⁵).", "c": 1, "x": {"1": "Dividiu só por R² (0,01 m²), esquecendo o 4π.", "2": "Dividiu por πR², esquecendo o fator 4.", "3": "Errou o expoente."}, "n": 3},{"id": "q198", "t": "di", "q": "Em um condutor carregado e isolado, com uma parte pontiaguda e uma parte achatada, a densidade superficial de cargas é:", "o": ["Maior na parte pontiaguda.", "Maior na parte achatada.", "A mesma em toda a superfície.", "Nula na parte pontiaguda."], "a": 0, "h": "Pense no poder das pontas.", "e": "As cargas se concentram nas regiões de menor raio de curvatura, como as pontas, onde a densidade superficial é maior.", "x": {"1": "A concentração acontece nas pontas, não nas partes achatadas.", "2": "A densidade só é uniforme em uma esfera isolada.", "3": "Nas pontas a densidade é maior, não nula."}, "n": 2},{"id": "q199", "t": "di", "q": "A mesma carga é distribuída uniformemente sobre uma superfície. Se a área da superfície for dobrada, a densidade superficial de cargas:", "o": ["Fica pela metade.", "Dobra.", "Fica quatro vezes menor.", "Não muda."], "a": 0, "h": "Densidade é carga dividida por área.", "e": "σ = Q / A. Com Q constante e A dobrada, σ cai à metade.", "x": {"1": "Dobra se a área cair pela metade, não se ela dobrar.", "2": "A relação com a área não é quadrática.", "3": "A densidade depende da área."}, "n": 1},{"id": "q200", "t": "di", "q": "Verdadeiro ou falso: a unidade da densidade superficial de cargas no Sistema Internacional é o C/m².", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Carga dividida por área.", "e": "Densidade superficial é carga por área: coulomb por metro quadrado.", "x": {"1": "A afirmação é verdadeira: σ = Q/A, em C/m²."}, "n": 1, "v": 1},{"id": "q201", "t": "di", "q": "Duas esferas condutoras de mesmo raio e mesma carga, uma maciça e outra oca, estão isoladas e em equilíbrio. A densidade superficial de cargas na superfície externa é:", "o": ["Igual nas duas.", "Maior na esfera maciça.", "Maior na esfera oca.", "Nula na esfera maciça."], "a": 0, "h": "Onde ficam as cargas em excesso de um condutor?", "e": "Em condutores em equilíbrio, as cargas ficam na superfície externa. Mesmo raio e mesma carga dão a mesma densidade.", "x": {"1": "A carga fica na superfície, não no volume, então maciça ou oca não importa.", "2": "A esfera oca não concentra cargas.", "3": "As cargas não ficam no interior da maciça."}, "n": 2},{"id": "q202", "t": "cp", "q": "Um capacitor, de modo geral, serve para armazenar:", "o": ["Carga elétrica e energia potencial elétrica no campo entre suas armaduras.", "Corrente elétrica.", "Calor.", "Apenas cargas positivas."], "a": 0, "h": "Pense em duas placas com cargas opostas.", "e": "O capacitor armazena cargas opostas em suas armaduras e, com isso, energia potencial elétrica no campo entre elas.", "x": {"1": "Corrente é movimento de cargas, não algo armazenado.", "2": "Não é um acumulador de calor.", "3": "Ele armazena cargas de sinais opostos."}, "n": 1},{"id": "q203", "an": "calc_q203", "t": "cp", "q": "Um capacitor armazena uma carga de 60 µC quando submetido a uma tensão de 12 V. Qual é a sua capacitância?", "o": ["5 µF", "720 µF", "0,2 µF", "72 µF"], "a": 0, "h": "Use C = Q / V.", "e": "C = Q / V = 60 µC / 12 V = 5 µF.", "c": 1, "x": {"1": "Multiplicou Q por V.", "2": "Inverteu a divisão (V / Q).", "3": "Somou Q e V."}, "n": 1},{"id": "q204", "an": "calc_q204", "t": "cp", "q": "Um capacitor de 20 µF é ligado a uma bateria de 9 V. Qual é a carga armazenada?", "o": ["180 µC", "2,2 µC", "29 µC", "0,45 µC"], "a": 0, "h": "Use Q = C · V.", "e": "Q = C · V = 20 µF × 9 V = 180 µC.", "c": 1, "x": {"1": "Dividiu C por V.", "2": "Somou C e V.", "3": "Dividiu V por C."}, "n": 1},{"id": "q205", "an": "calc_q205", "t": "cp", "q": "Um capacitor de 100 µF é carregado com uma tensão de 50 V. Qual é a energia armazenada nele?", "o": ["0,125 J", "0,25 J", "5,0 J", "2,5 × 10⁻³ J"], "a": 0, "h": "Use E = C·V²/2, com C em farad.", "e": "E = C·V² / 2 = 100 × 10⁻⁶ × 50² / 2 = 0,125 J.", "c": 1, "x": {"1": "Esqueceu de dividir por 2.", "2": "Usou V no lugar de V² e errou a escala.", "3": "Usou V (sem elevar ao quadrado) e dividiu por 2."}, "n": 2},{"id": "q206", "t": "cp", "q": "Ao inserir um material dielétrico entre as placas de um capacitor, a capacitância:", "o": ["Aumenta.", "Diminui.", "Não muda.", "Fica igual a zero."], "a": 0, "h": "O dielétrico permite armazenar mais carga para a mesma tensão.", "e": "O dielétrico aumenta a permissividade do meio entre as placas, e isso aumenta a capacitância.", "x": {"1": "Ele aumenta a capacitância, não a reduz.", "2": "A capacitância depende do meio entre as placas.", "3": "A capacitância não seria nula."}, "n": 2},{"id": "q207", "t": "cp", "q": "Em um capacitor de placas paralelas, a distância entre as placas é dobrada (área e meio iguais). A capacitância:", "o": ["Fica pela metade.", "Dobra.", "Fica quatro vezes maior.", "Não muda."], "a": 0, "h": "C é inversamente proporcional a d.", "e": "A capacitância é inversamente proporcional à distância entre as placas: dobrando d, C cai à metade.", "x": {"1": "Dobraria se a distância fosse reduzida à metade.", "2": "A relação não é quadrática.", "3": "A capacitância depende da distância."}, "n": 2},{"id": "q208", "t": "cp", "q": "Um capacitor está carregado. Se a tensão aplicada for dobrada, a energia armazenada:", "o": ["Fica quatro vezes maior.", "Dobra.", "Fica pela metade.", "Não muda."], "a": 0, "h": "A energia depende do quadrado da tensão.", "e": "E = C·V²/2. Com V dobrado, V² fica quatro vezes maior, e a energia também.", "x": {"1": "Dobraria se E fosse proporcional a V.", "2": "A energia aumenta com a tensão.", "3": "A energia aumenta com a tensão."}, "n": 2},{"id": "q209", "t": "cp", "q": "Verdadeiro ou falso: 1 farad é igual a 1 coulomb por volt.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "A unidade vem da definição C = Q / V.", "e": "C = Q / V, então 1 F = 1 C / 1 V.", "x": {"1": "A afirmação é verdadeira: farad é coulomb por volt."}, "n": 1, "v": 1},{"id": "q210", "an": "calc_q210", "t": "cp", "q": "Dois capacitores, de 6 µF e 3 µF, são ligados em série. Qual é a capacitância equivalente?", "o": ["2 µF", "9 µF", "4,5 µF", "18 µF"], "a": 0, "h": "Em série, some os inversos.", "e": "1/C_eq = 1/6 + 1/3 = 1/2, então C_eq = 2 µF.", "c": 1, "x": {"1": "Somou as capacitâncias (isso vale para a associação em paralelo).", "2": "Fez a média das capacitâncias.", "3": "Multiplicou as capacitâncias, sem dividir pela soma."}, "n": 2},{"id": "q211", "an": "calc_q211", "t": "cp", "q": "Três capacitores, de 2 µF, 3 µF e 5 µF, são ligados em paralelo. Qual é a capacitância equivalente?", "o": ["10 µF", "30 µF", "0,97 µF", "3,3 µF"], "a": 0, "h": "Em paralelo, some as capacitâncias.", "e": "Em paralelo as capacitâncias se somam: 2 + 3 + 5 = 10 µF.", "c": 1, "x": {"1": "Multiplicou as capacitâncias.", "2": "Somou os inversos, como em série, e errou o resultado.", "3": "Fez a média das capacitâncias."}, "n": 1},{"id": "q212", "an": "calc_q212", "t": "cp", "q": "Um capacitor de 4 µF está em série com um conjunto formado por dois capacitores de 3 µF ligados em paralelo. Qual é a capacitância equivalente da associação?", "o": ["2,4 µF", "10 µF", "1,5 µF", "7 µF"], "a": 0, "h": "Resolva primeiro o paralelo e depois a série.", "e": "O paralelo vale 3 + 3 = 6 µF. Em série com 4 µF: C_eq = 4×6/(4+6) = 2,4 µF.", "c": 1, "x": {"1": "Somou tudo (4 + 3 + 3).", "2": "Tratou os três como se fossem em série com valor igual.", "3": "Somou 4 e 3 e errou a ligação."}, "n": 3},{"id": "q213", "t": "cp", "q": "Em uma associação de capacitores, qual afirmação é correta?", "o": ["Em série, todos têm a mesma carga; em paralelo, todos têm a mesma tensão.", "Em série, todos têm a mesma tensão; em paralelo, todos têm a mesma carga.", "Em série e em paralelo, todos têm a mesma carga.", "Em série e em paralelo, todos têm a mesma tensão."], "a": 0, "h": "Série: um depois do outro. Paralelo: mesmos terminais.", "e": "Em série a carga é a mesma (Q constante) e as tensões se somam. Em paralelo a tensão é a mesma (V constante) e as cargas se somam.", "x": {"1": "Inverteu as grandezas constantes de cada associação.", "2": "Só em série a carga é igual.", "3": "Só em paralelo a tensão é igual."}, "n": 2},{"id": "q214", "an": "calc_q214", "t": "cp", "q": "Dois capacitores, de 6 µF e 3 µF, são ligados em série a uma fonte de 12 V. Qual é a carga em cada capacitor?", "o": ["24 µC", "72 µC", "36 µC", "4 µC"], "a": 0, "h": "Em série a carga é a mesma em todos. Calcule C_eq primeiro.", "e": "C_eq = 6×3/(6+3) = 2 µF. Em série a carga é a mesma e igual à da associação: Q = C_eq · V = 2 × 12 = 24 µC.", "c": 1, "x": {"1": "Usou a carga do capacitor de 6 µF ligado direto na fonte.", "2": "Somou as cargas de cada um ligado direto na fonte (72 + 36 não, usou 6 µF · 12 V).", "3": "Dividiu 12 V pelo número de capacitores e errou."}, "n": 3},{"id": "q215", "t": "cp", "q": "Três capacitores iguais, de capacitância C cada, são ligados em série. A capacitância equivalente é:", "o": ["C / 3", "3C", "C", "C / 9"], "a": 0, "h": "Some os inversos.", "e": "Em série, 1/C_eq = 3/C, então C_eq = C/3.", "x": {"1": "3C seria o valor em paralelo.", "2": "A capacitância equivalente em série é menor que C.", "3": "Somou o inverso errado."}, "n": 2}];